insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 1, 'The EGINA plan reads completeness 100 percent, 9 of 9 sections. What has the document established about those nine sections?', '["That each one carries a figure somebody entered, which is all the check counts: it reports what is present and what is missing and fills no gap.", "That each one was re-derived by the studio from the subsurface work, the well designs and the facility sizing behind the plan.", "That the nine sections agree with each other, because the check reconciles the concept capex against the cost items before it scores.", "That nine chapters of prose have been written, since the document scores the writing rather than the entries."]'::jsonb, 0, 'The same plan with no economics written scores 89 percent and carries the error "Total CAPEX is zero or missing.", so a section counts when it holds an entry and never because the entry was checked.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 2, 'A plan otherwise like EGINA, with its economics never written, scores 89 percent. Where does that figure come from?', '["The economics section is weighted above the others, because the NPV of 2047.5653 million USD is the figure the document leads on and the rest of it support.", "The score falls to the share of the six headline figures that survive, since the NPV and the IRR of 29.5998 percent both drop out when no economics are written.", "Eight of the nine sections still hold something, so the one empty section costs about a ninth of the score and the error names the CAPEX that is missing.", "A plan that fails validation is given a fixed penalty score, the same one a plan whose reserves rows cannot be parsed receives."]'::jsonb, 2, 'Completeness counts sections and does not weight them, and the error "Total CAPEX is zero or missing." names the one that is empty.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 3, 'A reader quotes EGINA''s NPV of 2047.5653 million USD off the plan''s headline and stops there. What is still missing?', '["Nothing further, since the NPV is the one headline figure the studio derives for itself, rather than reading it off an entry that somebody typed into the plan.", "Which capex it ran on, which price deck priced it and which production shape it burned, since one plan holds several answers to overlapping questions.", "The IRR of 29.5998 percent beside it, because a present value can only be read next to the rate of return the same case returned for that concept.", "The completeness score of 100 percent, because a plan scoring below it returns an NPV the studio marks provisional."]'::jsonb, 1, 'The same concept is worth 2047.5653 million USD at 70.0000 USD a barrel and -1797.2732 million USD at 18.0000, so the deck is part of the number.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 4, 'EGINA''s concept capex of 2250.0000 million USD and its cost items CAPEX total of 2250.0000 million USD are the same figure. What does that agreement tell a reader?', '["That the cost items are a roll-up of the concept''s drilling, facilities and subsea fields, so the two figures cannot disagree on any plan the studio holds.", "That the engine has reconciled the plan, since it refuses to price a plan whose line by line budget differs from the capex of the concept being priced.", "That the facility screening estimate of 1363.3524 million USD has been superseded, because two figures that agree outrank a single one that stands alone.", "That this plan was costed against the concept it is running, and no more than that."]'::jsonb, 3, 'They are two different measurements that happen to match here; a plan where they differ has a question in it, and the studio will not answer that question for you.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 5, 'The studio shows 1363.3524 million USD beside the plan''s other cost figures. What is that number measured from?', '["The concept''s facilities field of 1350.0000 million USD, carried through the sizing model and adjusted for the vessel''s gas and water handling capacity.", "The concept capex of 2250.0000 million USD less the 520.0000 of drilling and the 380.0000 of subsea, leaving what the vessel itself is estimated to cost.", "The facility type and its 60000 bopd nameplate, which makes it a class 5 figure covering the Egina FPSO alone and none of the drilling the plan carries.", "The plan''s own CAPEX cost lines for the vessel, which is why it sits below the 2250.0000 million USD that also carries drilling."]'::jsonb, 2, 'The 2250.0000 million USD comes from seven cost lines somebody wrote and the 1363.3524 from a type and a nameplate; both print to four decimals and are not the same class of number.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 6, 'The Egina FPSO returns a flow assurance level of Low on a fluid card with no H2S entry. What does that Low not rule out?', '["Corrosion, because the corrosion screen cannot fire at all without an H2S figure, so the blank field reads as no corrosion risk rather than as a question nobody has asked.", "Nothing at all, since the screen scores every hazard it knows against the fluid it was given and a Low means each one was tested and cleared.", "Hydrates, since the hydrate screen fires only where a line runs on the seabed and the Deep tie-back was the only item it was run against.", "Wax, since wax scores Medium on the Deep tie-back and a Medium is carried across to every facility sharing that fluid card."]'::jsonb, 0, 'Put 12 ppm of H2S on that fluid and the tie-back''s hazards read Hydrates High, Wax Medium and Corrosion High, so a Low is worth checking the missing fields against.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 7, 'Which four terms sit behind every scenario the screening tier prices unless the scenario overrides them?', '["Royalty 30.0000 percent, tax 12.5000 percent, discount 10.0000 percent and a variable operating cost of 5.0000 USD charged on every produced barrel of oil.", "Royalty 12.5000 percent, tax 30.0000 percent, an oil price of 70.0000 USD a barrel and a peak production rate of 60.0000 kbpd carried in from the concept.", "Tax 30.0000 percent, discount 10.0000 percent, an operating cost of 95.0000 million USD a year and a producing life of 20.0000 years taken from the concept.", "Royalty 12.5000 percent, tax 30.0000 percent, discount 10.0000 percent and a variable operating cost of 5.0000 USD a barrel that rides with the barrels."]'::jsonb, 3, 'The 5.0000 USD a barrel falls as production declines, and the discounting those four sit inside is mid year.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 8, 'The screening tier discounts mid year. What does that convention do to the answer?', '["It halves the 10.0000 percent discount rate for the first producing year, which is how the payback of 3.8273 years comes to fall between two whole years.", "It treats a year of production as arriving in the middle of the year, which is closer to how a field earns and gives a slightly higher present value than year end discounting on the same cash flow.", "It moves half of each year''s capex into the year before it is spent, so the deepest cash position of -2250.0000 million USD arrives one period earlier.", "It applies the 10.0000 percent rate at the middle of the 20.0000 year life rather than year by year, so a single factor prices the whole profile at once."]'::jsonb, 1, 'It is a timing convention on the same cash flow, and the NPV of 2047.5653 million USD carries it.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 9, 'On the EGINA Base case royalty takes 2011.8812 and tax 3310.0565 million USD. The studio reports 0.330657 alongside them. What is that ratio?', '["Government take of 5321.9377 million USD over the net cash flow the concept generates once its capex of 2250.0000 million USD and its operating cost have been taken out of revenue.", "Government take of 5321.9377 million USD over gross revenue of 16095.0492 million USD, royalty and tax added before any cost is taken out.", "The share of the NPV of 2047.5653 million USD that royalty and tax removed before the remainder was discounted at 10.0000 percent.", "The effective rate on profit, which is the 30.0000 percent tax lifted by the royalty charged ahead of it on the same barrels."]'::jsonb, 1, 'Capex of 2250.0000 and operating cost of 3049.6464 million USD sit outside that ratio: it is take over gross revenue and nothing else.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 10, 'The EGINA Base case never gets deeper than -2250.0000 million USD. Which year is that, and why that figure?', '["The payback year 3.8273 years in, where the cumulative position finally turns and the capex has just been recovered out of the producing years.", "The last year of the 20.0000 year life, where the decommissioning provision of 260.0000 million USD is charged against a profile that has declined to its lowest rate.", "The stress case at 18.0000 USD a barrel, where the same concept is worth -1797.2732 million USD and the cash position is at its lowest point in the plan.", "Year 0, which carries the capex and no production."]'::jsonb, 3, 'The whole 2250.0000 million USD of capex is spent before the first barrel is sold, so the deepest point is the year before revenue starts.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 11, 'A scenario priced at zero returns an NPV of -3517.4133 million USD, and a scenario with a blank oil price returns nothing at all. What separates them?', '["Zero is a number somebody entered, so the tier prices it, while a blank is a gap and the engine answers \"the scenario oil price is missing\" instead of deciding it.", "A blank is read as zero and then rejected for producing a negative value, since the engine declines any case worth less than the capex it carries.", "The engine puts its default oil price of 70.0000 USD a barrel behind a blank and reports the substitution, so no separate figure is returned.", "A price of zero skips royalty and tax, so the -3517.4133 million USD is capex and operating cost alone and a blank has no such shortcut."]'::jsonb, 0, 'The difference between those two cases is the difference between a decision and a gap, and the engine will not make the second one for you.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 12, 'Someone types the word lots into a capex box and the engine answers "the concept capex is not a number: lots". Why does the message repeat the word back?', '["Because the engine cannot name the field when the value it received is text, so it quotes the entry in place of the box the entry came from.", "Because a quoted value marks a warning rather than a refusal, so the case still runs on whichever capex field did hold a number.", "Because the offending value is searchable, so the reader can find the cell that holds it instead of walking the plan.", "Because the message is assembled from the cell reference, and lots is the heading the studio read that entry under."]'::jsonb, 2, 'Five refusals quote the value back, -500, -5, abc, x and lots, and every one of them names the field as well.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 13, 'Before the repair that preceded this course, a concept with no capex, no operating cost and no peak rate, priced by a scenario with no oil price, still returned a full set of screening economics. What was wrong with that output?', '["It was rounded to four decimals from values the engine held at full precision, so the NPV, the IRR and the payback disagreed with one another by small amounts.", "It was run on the other concept in the plan, the subsea tie-back, so the value of 1048.6281 million USD came back under the FPSO concept''s name instead.", "It carried a warning about the missing inputs which the studio printed in green, and readers took that green for a pass rather than for the notice it was.", "It was arithmetic on four figures the reader never saw."]'::jsonb, 3, 'The engine now stops instead and names the field: "the concept carries no capex: enter a drilling, facilities or subsea capex".'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 14, 'What can the screening tier not answer, on its own terms?', '["Whether one concept is worth carrying further than another, because one deck and one shape are applied to both and neither is tested on terms of its own.", "What to sign, since it models no ring fencing, uplift, cost recovery pool or tax holiday, and says nothing about how likely 70.0000 USD a barrel is.", "What a concept is worth after royalty and tax, because the tier reports gross revenue of 16095.0492 million USD and leaves the fiscal terms to the reader.", "Which figures the plan left blank, because it prices whatever it is handed and reports nothing when a concept field was never filled in."]'::jsonb, 1, 'Full fiscal detail under the PIA and the Nigeria Tax Act belongs to Petroleum Economics Studio, and this tier is one deck at one price on one shape.'),
  ('fdp', 'beginner', 'module', 'm01-what-a-plan-holds', 15, 'What does the studio do with the figures a plan carries?', '["It recomputes each figure from the study that produced it, which is how the reserves, the well designs and the facility sizing are kept in agreement inside one plan.", "It checks each figure against the engine''s published cases and flags any entry falling outside the range those cases cover before the plan is priced.", "It totals them, dates them and prices them, and re-derives no subsurface, no well design and no facility sizing of its own.", "It grades each figure by the class of estimate behind it, so a class 5 number is marked apart from a costed line."]'::jsonb, 2, 'A figure typed into it is only as good as the work behind it: a reserves row of 95.0000 MMbbl at P50 is a number a subsurface team handed over, and the studio never checks the geology.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 1, 'EGINA''s oil P50 of 130.0000 MMbbl was summed from which rows, and with what else in it?', '["The three reservoir rows at P50, with the Egina Gas Cap''s 70.0000 converted to a barrel of oil equivalent before the column was added.", "Egina Main at 95.0000 and Egina Deep at 35.0000, the two oil rows, and nothing else.", "Egina Main at 95.0000 and Egina Deep at 35.0000, each weighted by its recovery factor of 0.340000 and 0.280000 before the two were added.", "The oil P90 of 80.0000 MMbbl and the oil P10 of 205.0000 MMbbl averaged, since a P50 sits in the middle of the range the rows describe."]'::jsonb, 1, 'Each column is the arithmetic sum of that column within one fluid, so the gas row of 70.0000 Bcf stays in its own unit and the recovery factors never enter the sum.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 2, 'The engine reports the gas total as 1 row summing to 70.0000 Bcf. Why does that row count matter as much as the total does?', '["A single row is held as provisional until a second gas reservoir is entered, because the engine will not aggregate a distribution out of one estimate.", "The count sets the band on the total, so a one row fluid is given a wider spread from 40.0000 to 110.0000 than two rows of the same size would carry.", "The count divides the total to give an average reservoir size, catching a fluid whose rows were entered twice.", "A fluid with one row has no aggregation in it, so 70.0000 Bcf is one reservoir estimate carried straight through."]'::jsonb, 3, 'The oil total of 130.0000 MMbbl is two rows added and carries the sum of low cases question with it, and the gas total of 70.0000 Bcf does not.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 3, 'Egina Main carries a recovery factor of 0.340000 and Egina Gas Cap carries 0.650000. What do those two figures contribute to the totals the engine reports?', '["Nothing at all: the engine adds the P90, P50 and P10 columns and never touches the recovery factor, which is context for the volume and not an input to the sum.", "They scale each row before it is summed, which is why the oil P50 of 130.0000 MMbbl comes out below the two rows added at face value.", "They decide which rows may be summed together, since only rows sharing a recovery band are added into one fluid total.", "They turn each row from oil in place into a recoverable volume, so 95.0000 MMbbl is 0.340000 of what the Egina Main zone holds."]'::jsonb, 0, 'A row with 0.340000 in it and a row with 0.650000 in it add exactly the same way; the factor says what fraction of the oil in place that estimate assumed.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 4, 'A row named Aquifer is entered with its fluid typed as Brine. What does the engine return, and what decides the wording?', '["The row is dropped from the totals and a warning lists the three fluids the engine knows, so the oil and gas figures still come back with the readable rows summed.", "The row is given a fourth column of its own, since the engine opens a column for any fluid label it has not met before.", "\"Aquifer: fluid type is missing or unknown (Brine); expected one of Oil, Gas, Condensate\", led by whatever was typed in the name column.", "The row is refused by its position as \"row 2\", because a fluid the engine cannot read leaves it nothing to call the row by."]'::jsonb, 2, 'An unnamed row is the one refused by position: "row 2: fluid type is missing or unknown (undefined); expected one of Oil, Gas, Condensate".'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 5, 'A slide adds EGINA''s oil P50 of 130.0000 MMbbl to its gas P50 of 70.0000 Bcf and prints 200.0000. What has it produced?', '["A barrel of oil equivalent total, which is defensible as long as the heating value used to convert the 70.0000 Bcf is stated beside it.", "The field''s total recoverable volume at P50, which is the figure the generated document carries in its headline for the plan as a whole.", "A correct total in MMbbl, since Bcf is a reporting unit and both columns share one unit.", "A figure in no unit at all, neither barrels nor cubic feet, which can be checked against nothing."]'::jsonb, 3, 'The engine returns one total per fluid in that fluid''s own unit: a million barrels and a billion standard cubic feet are different things sold into different markets.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 6, 'The published three fluid case returns oil P50 105.0000 MMbbl, gas P50 30.0000 Bcf and condensate P50 4.0000 MMbbl. Why is the condensate kept out of the oil total when both are measured in MMbbl?', '["That case holds two oil rows and one condensate row, and the engine adds only rows whose count matches within a fluid.", "A condensate barrel and a crude barrel are not the same barrel and are not priced the same way.", "Condensate comes out of the gas phase, so the engine totals it with the 30.0000 Bcf and prints it in MMbbl for the reader.", "The engine holds it apart until a conversion factor is entered, then folds it into oil."]'::jsonb, 1, 'Oil, Gas and Condensate are the three fluids the engine knows, and each one is totalled in its own column and its own unit.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 7, 'A volumetric run on the Egina Main zone returns 403.5392 MMstb. What does the reader now hold?', '["A reserves estimate for that zone, since the calculation has already taken the water saturation of 0.220000 out of the pore space.", "A recoverable volume at surface, since the formation volume factor of 1.310000 has already shrunk it to stock tank barrels.", "An in place volume, which becomes reserves only after a recovery factor carrying the concept, the drive mechanism, the well count and the producing years inside it.", "A check on the reserves table, since a zone in place volume and the plan''s oil P50 of 130.0000 MMbbl estimate one quantity."]'::jsonb, 2, 'Quoting 403.5392 MMstb to somebody who hears reserves is the most expensive rounding error available in this studio, and no arithmetic in the plan catches it.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 8, 'The oil column sums to 80.0000 MMbbl at P90. Why is that not the field''s low case?', '["It is 60.0000 plus 20.0000, a volume the field reaches only if both reservoirs disappoint in the same world, so the true field low case sits above it.", "It leaves out the gas cap''s P90 of 40.0000 Bcf, and a field low case is both columns added together once the gas has been converted onto a barrel basis for the sum.", "It is a median rather than a mean, and a median does not add, so the sum falls short of the field by that difference.", "It sums rows carrying different recovery factors, 0.340000 and 0.280000, and a column may only be added within one factor."]'::jsonb, 0, 'Two reservoirs disappointing together is less likely than either one disappointing alone unless they share the cause, so a sum of low cases is pessimistic by construction.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 9, 'Under what condition would 80.0000 MMbbl be a fair low case for the field as a whole?', '["If both rows had been entered at one recovery factor, since the column adds honestly only where a single factor runs across the field.", "If the plan carried a third oil row, since more rows in a fluid pull the sum towards the field distribution itself.", "If the two reservoirs are the same play, charged from the same kitchen and sharing one structural interpretation, so they really would disappoint together.", "If the rows had been aggregated rather than added, since aggregation and addition agree at the low case and part company higher up."]'::jsonb, 2, 'Independent reservoirs pull the field distribution inwards and perfectly correlated ones do not; the engine cannot know which EGINA is, so it adds the columns and says what it did.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 10, 'The oil P10 of 205.0000 MMbbl is 145.0000 plus 60.0000. Where does the field''s own high case sit against that figure?', '["Below it, because 205.0000 MMbbl asks both reservoirs to deliver their high cases at once, and that is less likely than either delivering alone.", "Above it, because adding two high cases understates the upside of a field in the same way that adding two low cases understates how badly it could do.", "Exactly on it, because the P10 column is the one column that does add correctly across the rows of a single fluid.", "Nowhere readable, because the P10 is a percentile of a distribution the engine never built and only the P50 can be placed."]'::jsonb, 0, 'The sum of low cases is too low and the sum of high cases too high, and the fix in both directions is to aggregate the distributions rather than the percentiles.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 11, 'Which figure in the EGINA plan may carry a P90 label?', '["The capex of 2250.0000 million USD, whose own uncertainty is written in the same percentile language the reserves rows use.", "The NPV of 2047.5653 million USD, since the uncertainty in the reserves is carried through the case into the value it returns.", "The recovery factor of 0.340000, which is a percentile of the range of factors that reservoir could turn out to deliver.", "The oil reserves low case of 80.0000 MMbbl."]'::jsonb, 3, 'P-labels belong to a reserves distribution and to one fluid at a time; a capex carries uncertainty and that uncertainty is written in P-labels nowhere in this studio.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 12, 'A plan whose reserves came from a loaded example carries a P50 of 130.0000 and an empty table. What does it score, and what is that score for?', '["100 percent with isValid true, because the P50 the plan reports is the figure the rows would have totalled to anyway.", "33 percent with isValid true, loud enough to send the reader looking for the rows.", "0 percent with isValid false, because a summary carried in from an example is not an entry anybody made on this plan.", "89 percent with isValid false, because reserves is the one section of the nine the completeness check could not read here."]'::jsonb, 1, 'A summary is something rather than nothing, so the plan stays valid; the 130.0000 reads with nothing underneath it to check, and the score says so.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 13, 'A plan with a full reserves table and an empty summary box now scores 100 percent and is valid. What did the repair that preceded this course change about it?', '["Before the repair it scored 78 and failed, because the check read the summary field alone and a table nobody had summarised counted for nothing.", "Before the repair it read the rows but totalled them across fluids, so oil and gas were added together before the score was struck.", "Before the repair it refused the plan by name, reporting the blank summary the way a missing oil price is reported today.", "Before the repair it took the P50 from the concept''s production shape, so the score was struck on a volume nobody had entered."]'::jsonb, 0, 'The reserves were there the whole time, and the completeness check, the generated document and the economics now reach them through one accessor.'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 14, 'A plan whose reserves table cannot be read reports a P50 of 0.0000 beside a completeness of 89 percent. What is that pair telling the reader?', '["That the reserves really are zero, since a table the engine cannot read holds nothing that counts as an estimate.", "That the summary figure of 130.0000 MMbbl stood in for the rows, which is why the score stays as high as 89 percent.", "That a reserves section was found and could not be parsed, so no volume was invented and the fix is in the table.", "That eight of the nine sections failed validation and reserves is the one that survived."]'::jsonb, 2, 'It reports 0.0000 rather than a plausible figure, and the published case of an unreadable table scores 22 percent with the error "Reserves (P50) not estimated."'),
  ('fdp', 'beginner', 'module', 'm02-reserves-per-fluid', 15, 'The implied recovery factor of 0.322150 is the oil P50 of 130.0000 MMbbl over an OOIP of 403.5392 MMstb. What is wrong with reading it as this field''s recovery factor?', '["It falls between the 0.340000 and the 0.280000 the reserves table states, so it is an average of those two and not a figure in its own right.", "The 130.0000 MMbbl totals two reservoirs and the 403.5392 MMstb is one zone''s oil in place, so the ratio divides two different footprints.", "It was built on an OOIP the studio measured rather than on the mapped area of 2400.0000 acres and the 140.0000 ft of net pay.", "It sets a P50 volume against an in place figure quoted at P90, so the two sides of the ratio are read at different percentiles."]'::jsonb, 1, 'Two numbers that each came from the engine can still be the wrong pair: 0.322150 is a screening cross check and not a reservoir engineering result.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 1, 'The FPSO development concept holds drilling 520.0000, facilities 1350.0000 and subsea 380.0000. What does the engine do with those three fields?', '["It reads the largest of them, the 1350.0000 million USD of facilities, and treats the drilling and subsea figures as a breakdown sitting behind it.", "It adds the drilling and the facilities and holds the 380.0000 of subsea back, since subsea hardware is charged against the tie-back concept.", "It reads all three and runs the screening economics on their sum of 2250.0000 million USD.", "It prices each field as its own case and reports three NPVs."]'::jsonb, 2, 'The tie-back reaches 730.0000 the same way from 240.0000, 180.0000 and 310.0000, and the FPSO''s year 0 cash flow row is -2250.0000, the whole capex before production starts.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 2, 'The tie-back carries 310.0000 million USD of subsea against 180.0000 of facilities, while the FPSO carries 1350.0000 of facilities against 380.0000 of subsea. What does that split tell you?', '["What kind of development each one is: the FPSO puts its money into the vessel, and the tie-back puts more into subsea hardware because it hangs off a host that already exists.", "That the tie-back''s subsea scope is the larger of the two in absolute terms, which is what lets it reach first oil a full year earlier.", "That the two concepts were costed by different teams, since a subsea figure above a facilities figure is the mark of a hardware estimate.", "That the tie-back is the more expensive development, since two of its three fields are larger than the matching FPSO fields."]'::jsonb, 0, 'The FPSO totals 2250.0000 million USD and the tie-back 730.0000, and the split says where each of them spends it.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 3, 'A concept is entered carrying a facilities figure of 1350.0000 million USD with the drilling and subsea boxes left empty. What does the engine return?', '["A refusal naming the two empty boxes, since a concept must carry a drilling, a facilities and a subsea figure before the engine will price it.", "A total of 2250.0000 million USD, the empty fields filled from the other concept of that type which the plan already holds.", "A warning that the capex is incomplete, with the screening case held back until the two empty fields are filled in or confirmed as zero.", "A total capex of 1350.0000 million USD, and no complaint."]'::jsonb, 3, 'A blank capex field is zero rather than missing: a concept with at least one capex figure has a capex, and the refusal fires only when all three are empty.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 4, 'What comes back when all three of a concept''s capex fields are empty?', '["A screening case on a capex of zero, so the NPV is the discounted revenue of the production shape with no capital charged against it anywhere in the case.", "The refusal \"the concept carries no capex: enter a drilling, facilities or subsea capex\", which names the fields that would satisfy it.", "A total capex of 100 million USD, the default the engine once substituted and still applies when every capex box is blank.", "A refusal on the scenario instead, since an oil price cannot be applied to a concept whose capital cost is unknown."]'::jsonb, 1, 'Strip the capex fields off the EGINA FPSO concept and the same message comes back, and the case stops there rather than running on a figure nobody entered.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 5, 'A planner types -520 into the drilling capex box of the EGINA FPSO concept. What does the engine answer?', '["\"the drilling capex may not be negative: -520\", which names the field and quotes the value back so the cell can be found.", "It takes the value as entered in magnitude and prices the concept on the full 2250.0000 million USD, noting in the case the sign that it corrected.", "It nets the -520 against the facilities figure of 1350.0000 million USD and prices the concept on what is left.", "It refuses the whole plan, since a negative entry anywhere in the concepts section stops the document being generated."]'::jsonb, 0, 'A capex typed as text comes back the same way, "the concept capex is not a number: lots", naming the field and repeating what was typed.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 6, 'A concept is entered with its drilling and subsea figures typed and its facilities cost left for later. What happens when somebody prices it?', '["It is refused until the facilities cost is entered, since the engine checks a concept''s three fields against its concept type before pricing.", "It is priced on the facilities figure carried by the other concept in the plan, 180.0000 million USD, as the nearest estimate the studio holds.", "It returns a screening NPV on a capex missing its largest component, and complains about nothing.", "It is priced and marked provisional, with a note naming the empty field."]'::jsonb, 2, 'A concept with one populated field has a capex, so the refusal fires only when all three are empty: check the three fields against the total before quoting anything downstream.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 7, 'A planner puts the whole 2250.0000 million USD into one capex box rather than into the three fields. What does the engine return, and what has gone?', '["A refusal, since a pre-totalled figure is not one of the three fields the engine reads and the concept counts as uncosted.", "The same total capex of 2250.0000 million USD, and with it the split that said how much was drilling, how much facilities and how much subsea.", "The same total, and nothing has gone, since the three fields are a display and the engine adds them into one figure before it prices anything.", "A total of 2250.0000 million USD booked as facilities, since a single capex entry is carried into the largest of the three fields."]'::jsonb, 1, 'A concept with at least one capex figure has a capex, so nothing complains; the split of 520.0000, 1350.0000 and 380.0000 is what said the money was going into a vessel.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 8, 'How does the FPSO development reach a lifecycle cost of 4150.0000 million USD?', '["Capex of 2250.0000 plus the operating cost of 3049.6464 million USD that the Base case burns over the profile it prices.", "Capex of 2250.0000 plus 1900.0000 of operating cost plus the decommissioning provision of 260.0000 million USD in the cost breakdown.", "Capex of 2250.0000 discounted at 10.0000 percent plus the 95.0000 a year.", "Capex of 2250.0000 plus 95.0000 a year across 20.0000 years, which is 1900.0000."]'::jsonb, 3, 'The tie-back reaches 1330.0000 the same way, 730.0000 plus 40.0000 across 15.0000 years, and nothing in either sum is discounted.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 9, 'What is the life field of 20.0000 years doing to the FPSO''s lifecycle cost?', '["Discounting the operating cost across 20.0000 years, which is how 95.0000 a year comes to 1900.0000 rather than a larger figure.", "Turning the annual 95.0000 million USD into the 1900.0000 added to the capex, so a life longer than the concept will really run overstates the total by the difference.", "Setting the years the production shape declines over, with no part in the lifecycle sum itself.", "Capping the operating cost at the capex of 2250.0000 million USD, which is why the 1900.0000 stops short of it."]'::jsonb, 1, 'Operating cost of 1900.0000 million USD is most of the way to the 2250.0000 of capex, so the life field is carrying real weight in that total.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 10, 'The lifecycle totals are 4150.0000 million USD for the FPSO and 1330.0000 for the tie-back. What can that pair of figures not do?', '["Say how much cash each concept consumes in total, which needs a year by year profile rather than a plain sum of two cost lines.", "Show which concept commits more capital, since the operating cost of 1900.0000 million USD dominates the FPSO''s own total.", "Be set against each other at all, since the two concepts run for different lives of 20.0000 years and 15.0000 years.", "Rank the two concepts by value."]'::jsonb, 3, 'A lifecycle cost is money as it is spent, with no discounting, no price, no royalty and no tax in it, and the ordering by value comes from the NPVs of 2047.5653 and 1048.6281 million USD.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 11, 'The EGINA cost breakdown carries a decommissioning provision of 260.0000 million USD typed as ABEX. Where does it sit inside the concept''s lifecycle of 4150.0000 million USD?', '["In the operating cost of 1900.0000 million USD, spread across the 20.0000 years the concept is expected to run for.", "In the capex of 2250.0000 million USD, since a provision is committed at sanction with the rest.", "Nowhere: the engine''s totals are CAPEX 2250.0000 and OPEX 95.0000 a year, and an ABEX line is in neither of them.", "In the final year of the profile, where the Base case charges it against a declining revenue."]'::jsonb, 2, 'Facilities carry their own estimate of the same thing, 204.5029 million USD for the Egina FPSO, so two real figures for the end of life sit outside the 4150.0000.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 12, 'The FPSO concept''s profile reads 60.0000, 60.0000, 60.0000, 54.0000, 48.6000 and 43.7400 kbpd. How is that 54.0000 arrived at?', '["Year 3 multiplied by 0.900000, the fixed factor applied to every year once the plateau ends at year 3.", "The peak of 60.0000 kbpd cut by the share of the life already produced.", "The peak of 60.0000 kbpd scaled to what is left of the oil P50 of 130.0000 MMbbl after three years at plateau.", "The rate the reservoir can still deliver once the plateau wells decline, which the engine reads off the recovery factor."]'::jsonb, 0, 'The factor never changes, so year 5 is 48.6000 and year 6 is 43.7400, and the last year of the profile reads 10.0063 kbpd.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 13, 'A peak rate and a life draw the whole screening profile. What does the engine check that profile against before returning a screening case?', '["The oil P50 of 130.0000 MMbbl, which is why a plateau the reserves cannot feed is cut back before the case is priced.", "The 4 wells the plan carries, so the plateau is held to what those wells can deliver at the concept''s peak rate.", "The recovery factors of 0.340000 and 0.280000 in the reserves table, which set how steeply the profile may decline.", "Nothing at all."]'::jsonb, 3, 'The plan''s oil P50 of 130.0000 MMbbl is never consulted, so a concept whose plateau and life the reserves cannot support still returns a full set of screening economics.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 14, 'An FPSO concept is given a start date of 2028-02-29. When does it reach first oil, and why that date?', '["The last day of February in that year, because a start on a leap day is moved back before the whole months are added.", "2031-03-01, because the engine adds the 36 whole months an FPSO carries and lands on a date that exists.", "2030-04-01, because first oil for this concept type is fixed there.", "It is refused, because the engine will not date a schedule from a leap day."]'::jsonb, 1, 'The duration belongs to the concept type, 36 months for an FPSO against 24 for the tie-back, so moving the sanction date moves first oil with it.'),
  ('fdp', 'beginner', 'module', 'm03-concepts-and-their-capex', 15, 'A concept carries no start date and no today is passed in. What does the engine do, and what is the refusal protecting?', '["It answers \"the concept has no start date: enter one, or pass today to date the schedule from\", so that no date in a plan is ever picked up off the machine that opened it.", "It dates the schedule from the day the plan was opened and stamps that day on the case, so a reader can see which one was used.", "It dates the schedule from the other concept''s sanction date of 2027-04-01 and records where the date was borrowed from.", "It returns the 36 months as a duration with no dates attached and leaves the reader to place it on a calendar."]'::jsonb, 0, 'A schedule that dates itself from a clock slips every day nobody opens it, so two people reading one plan a month apart get different first oil dates.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 1, 'The same FPSO concept returns an NPV of -161.0098 million USD at 40.0000 USD a barrel and 3151.8529 at 85.0000 USD a barrel. What differs between those two runs?', '["The peak rate, because the engine trims the plateau of 60.0000 kbpd when a price cannot support it, so the cheaper run lifts fewer barrels as well.", "The discount rate, because a run priced at 40.0000 is discounted above the default 10.0000 percent.", "Only the price at the head of each run: the capex of 2250.0000, the 20 year shape and the fiscal terms are identical.", "The fiscal terms, because the royalty of 12.5000 percent is charged only once a case can pay it."]'::jsonb, 2, 'Four evenly spaced prices give -161.0098, 943.2778, 2047.5653 and 3151.8529, and the value steps up by the same amount each time because only what a barrel earns moves.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 2, 'A scenario priced at 0 returns an NPV of -3517.4133 million USD, while a scenario whose price box is left empty returns no value at all. What separates the two inputs?', '["A typed zero is a number somebody chose, so the engine answers it; a blank is refused by name with the message that the scenario oil price is missing.", "Nothing in the inputs, because a blank reads as zero and both runs land on -3517.4133, with the missing price only noted.", "The sign of the entry, because zero is inside the accepted band while a blank reads as a negative price and is stopped as one.", "The default, because a blank price falls back to the 70.0000 USD a barrel the studio substitutes and quietly returns the Base value of 2047.5653."]'::jsonb, 0, 'Zero is accepted and returns -3517.4133; the silent substitution of 70.0000 USD a barrel ended in September 2026, and a missing price is now refused by name.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 3, 'The Stress scenario at 18.0000 USD a barrel reports an NPV of -1797.2732, an IRR status of no-root and a payback of never. What does that payback state?', '["That payback falls in the last year of the 20.0000 year life, since a case ending at -1797.2732 has recovered all but that part of its capex of 2250.0000.", "That payback could not be computed because the rate of return has status no-root, and the engine withholds both figures whenever either one of them fails.", "That the capex of 2250.0000 is recovered exactly at the end of the profile, so the crossing sits on the last of the 21 rows the case carries.", "That the cumulative cash position never crosses zero, so a refusal is reported in place of a number."]'::jsonb, 3, 'The cumulative opens at -2250.0000 and never climbs out at that price; 5.7734 years at 48.0000 USD a barrel and never at 18.0000 are answers of the same kind, one measured and one refused.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 4, 'The Base case takes 2011.8812 of royalty and 3310.0565 of tax out of gross revenue of 16095.0492. A reader quotes the tax alone as what the state receives. What has that reader left out?', '["Nothing of the state''s money, because royalty is charged to the operator''s own account beside the operating cost of 3049.6464 and never enters the government take.", "The royalty of 2011.8812, so the state''s 5321.9377, which is 0.330657 of gross revenue, is understated by that whole line.", "The capex of 2250.0000, which is recovered from the state before tax is charged.", "The discounting, because the take of 5321.9377 is a present value while the tax is money of the day."]'::jsonb, 1, 'Government take is royalty plus tax, 5321.9377 against gross revenue of 16095.0492, which is a share of 0.330657.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 5, 'Year 1 of the Base case earns gross revenue of 1533.0000 and is charged a royalty of 191.6250. Where does the 191.6250 come from?', '["The default royalty of 12.5000 percent applied to that year''s own gross revenue, charged year by year rather than on the life total.", "The life royalty of 2011.8812 spread evenly across the producing years, which gives each of them the same charge.", "The royalty of 12.5000 percent applied after the operating cost of 204.5000 is taken off the year''s revenue.", "The tax rate of 30.0000 percent applied to the net cash flow of 795.8125 that the year closes with, before any discounting."]'::jsonb, 0, '12.5000 percent of 1533.0000 is 191.6250, and years 1, 2 and 3 carry the same charge because each earns the same 1533.0000 on the plateau.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 6, 'The concept carries a fixed operating cost of 95.0000 million USD a year, yet year 1 of the Base case is charged 204.5000 and year 4 is charged 193.5500. What accounts for both figures?', '["The operating cost is grown each year at the discount rate of 10.0000 percent, so year 4 carries four years of that escalation on the 95.0000.", "The 95.0000 is stated after the royalty of 12.5000 percent, and the engine grosses it back up before charging it, which lifts every row above it.", "A variable 5.0000 USD on every barrel is added to the fixed 95.0000, and year 4 lifts fewer barrels than a plateau year.", "The decommissioning provision of 260.0000 is spread across the 21 rows of the case."]'::jsonb, 2, 'Fixed 95.0000 plus 5.0000 USD a barrel gives 204.5000 on a full plateau, and the fixed part does not move when the rate declines, so year 4 falls only to 193.5500.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 7, 'Year 0 of the Base case shows gross revenue of 0.0000 and capex of 2250.0000. What should a reader do with that row?', '["Treat the blank revenue as missing data and enter the plateau rate of 60.0000 kbpd against it, since no year is empty.", "Read it as the answer: the whole capex is spent in the year before production, and first oil is 36 months after sanction on this concept.", "Read the -2250.0000 in its cumulative column as the loss the plan makes and the later rows work to cover.", "Spread the capex of 2250.0000 over the three plateau years, since the subsea system is installed while the field produces."]'::jsonb, 1, 'Year 0 is the build, so the cumulative opens at -2250.0000, the deepest cash position the case reaches, and the capex column reads 0.0000 for the rest of the life.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 8, 'The Base case reports a deepest cash position of -2250.0000 million USD. What is that figure?', '["The loss the case carries to the end of its life, which the NPV of 2047.5653 states once the discount of 10.0000 percent has been applied to it.", "The part of the capex still outstanding after the plateau, since years 1 to 3 each return 795.8125 of net cash flow against a spend of 2250.0000.", "The cumulative position at the end of the 21 rows, once the decline has run down to 10.0063 kbpd and the field stops earning.", "The furthest the plan is ever out of pocket, reached at year 0 and closed by year 3."]'::jsonb, 3, 'The cumulative opens at -2250.0000 and stands at 137.4375 after year 3, so the deepest position is a moment in the case and not its result.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 9, 'Payback on the Base case is 3.8273 years. Which two cumulative cash positions does that crossing sit between?', '["-1454.1875 after year 1 and -658.3750 after year 2, because the hole is closed once two plateau years of 795.8125 have been earned against it.", "137.4375 after year 3 and 847.0187 after year 4, because the crossing is dated from the first row whose cumulative column is positive onward.", "-658.3750 after year 2 and 137.4375 after year 3, with the crossing placed inside year 3.", "-2250.0000 at year 0 and -1454.1875 after year 1, counting from the spend."]'::jsonb, 2, 'The cumulative reads -658.3750 after year 2 and 137.4375 after year 3, and the engine places the crossing by how far into that year the remaining hole is closed.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 10, 'Year 4 of the Base case earns 709.5812, year 5 earns 631.9731, and the decline runs on to the end of the 21 rows. How much of that money reaches the payback figure of 3.8273 years?', '["All of it, because payback is measured on the same discounted flow as the NPV of 2047.5653 and therefore reads the whole of the life.", "None of it, because payback stops at the crossing, while the NPV of 2047.5653 counts every one of the 21 rows.", "Year 4 alone, because the crossing at 3.8273 years counts the rest of that year.", "The money earned before the decline begins, so 709.5812 counts and the later rows do not."]'::jsonb, 1, 'Two cases with the same payback can hold quite different money after the crossing, and only a value figure such as 2047.5653 can tell them apart.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 11, 'The tie-back pays back in 3.2035 years and the FPSO in 3.8273 years at the same 70.0000 USD a barrel. What does a reader who ranks the two on payback alone give up?', '["The larger value, because the quicker concept is worth 1048.6281 against the FPSO''s 2047.5653 at that price.", "Nothing measurable, because the tie-back also carries the higher rate of return at 40.4321 percent against 29.5998, so every measure agrees with it.", "The lower capex, because a payback ranking selects the FPSO''s spend of 2250.0000 over the tie-back''s 730.0000, which is the harder of the two to fund.", "The longer life, because a ranking on payback prefers 20.0000 years to 15.0000."]'::jsonb, 0, 'The quicker concept is the smaller one, 1048.6281 against 2047.5653 at one price, so a payback ranking puts the smaller value first.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 12, 'At 70.0000 USD a barrel the tie-back returns 1.436477 per million USD of capex and the FPSO returns 0.910029. What does that pair of ratios not say?', '["Which of the two spends less, because the ratio is built on the capex of 730.0000 and 2250.0000 and reports the cheaper concept as the higher figure.", "Which concept the studio selects, because a ratio above one marks a development the engine passes and 0.910029 marks one it holds back.", "How the two would rank on their rates of return, because the ratio is the rate of 40.4321 percent restated for each million USD of capex.", "How much value each concept leaves in total, because a ratio has no size in it."]'::jsonb, 3, 'On a budget that can carry 2250.0000 the FPSO leaves 2047.5653 where the tie-back leaves 1048.6281, and the ratio of 1.436477 says nothing about that gap.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 13, 'The FPSO concept''s lifecycle cost is 4150.0000 million USD and the tie-back''s is 1330.0000. What is each figure made of?', '["Capex of 2250.0000 with the decommissioning provision of 260.0000 and the 3049.6464 of operating cost the Base case charges across its life.", "Capex of 2250.0000 with 1900.0000 of operating cost over 20.0000 years, against 730.0000 with 600.0000 over 15.0000 years.", "The capex each concept carries grossed up by the royalty of 12.5000 percent and the tax of 30.0000 percent.", "The capex each concept asks for added to the value it earns, 2047.5653 on 2250.0000."]'::jsonb, 1, 'Lifecycle is capex plus operating cost over the concept''s own life, so 2250.0000 and 1900.0000 give 4150.0000, and 730.0000 and 600.0000 give 1330.0000.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 14, 'A tie-back is entered with drilling capex of 240.0000 and facilities capex of 180.0000, and its subsea line of 310.0000 is never typed. What does the engine do with it?', '["It refuses the concept by name, because the message about a concept carrying no capex is raised whenever one of the three capex fields is empty.", "It substitutes the missing line from the FPSO concept''s subsea capex of 380.0000, scaled to the tie-back''s peak of 25.0000 kbpd, and marks it as estimated.", "It screens the concept on the two fields it carries, because only a concept with no capex at all is refused.", "It falls back to the concept capex of 100 million USD that nobody typed."]'::jsonb, 2, 'The engine reads all three fields and totals what is there, so the concept is screened on less than the 730.0000 it costs, and the refusal is kept for a concept carrying no capex at all.'),
  ('fdp', 'beginner', 'module', 'm04-what-a-scenario-is-worth', 15, 'The Base case reports 2047.5653 million USD at a discount rate of 10.0000 percent taken mid year. What does that figure state?', '["What the case is worth against earning 10.0000 percent elsewhere, with the cash treated as arriving through each year.", "The cash the plan pays out, because the undiscounted total of the 21 rows comes to 2047.5653.", "What is left once the government take of 5321.9377 is paid, with the discount applied to the capex alone.", "The value at the end of the 20.0000 year life, carried forward at 10.0000 percent from year 0."]'::jsonb, 0, 'Nothing in a plan pays out 2047.5653: the figure is a comparison against a 10.0000 percent alternative, and mid year treatment puts the cash through the year rather than on its last day.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 1, 'The engine reports CAPEX 2250.0000 and OPEX 95.0000 a year for a plan whose seven items total more than those two figures together. Which line reaches neither total?', '["The mooring and installation line of 170.0000, which sits inside the Installation phase of 550.0000 rather than in the capex.", "The decommissioning provision of 260.0000, typed as ABEX, which is visible only in the Operate phase roll-up of 355.0000.", "The maintenance and integrity line of 23.0000, which is held outside the yearly total because it is charged on the barrels.", "The subsea system of 380.0000, which the concept already carries in a capex field of its own."]'::jsonb, 1, 'A screening case carries capex and operating cost only, so the ABEX line of 260.0000 is in neither the CAPEX total of 2250.0000 nor the OPEX total of 95.0000.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 2, 'A reader takes the Operate phase roll-up of 355.0000 million USD as the plan''s annual operating cost. What has that reader picked up?', '["The right figure for the plan''s own case, because the screening economics charge the whole Operate phase in every year of the 20.0000 year life.", "The operating cost with the variable 5.0000 USD a barrel in it, as year 1 shows.", "The operating cost over the life, 95.0000 a year with the provision of 260.0000.", "A phase total, of which 260.0000 is the decommissioning provision, in place of the 95.0000 a year."]'::jsonb, 3, 'Operate is 355.0000 because three lines sit in it, and read as an annual figure it charges the plan nearly four times what its economics charge it.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 3, 'The Installation phase of the plan totals 550.0000 million USD. Which cost items make up that total?', '["Mooring and installation at 170.0000 together with the subsea system at 380.0000.", "The subsea system at 380.0000 with the part of the drilling line of 520.0000 that is spent offshore.", "The FPSO hull and topsides at 1180.0000 less the mooring and installation line of 170.0000.", "Development drilling at 520.0000 with maintenance and integrity at 23.0000."]'::jsonb, 0, 'Two of the seven lines sit in Installation, 170.0000 and 380.0000, against Execution 520.0000, Construction 1180.0000 and Operate 355.0000.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 4, 'A decommissioning provision is typed into the cost items as CAPEX rather than as ABEX. What does the engine do with it?', '["It refuses the line by name, as it refuses a negative drilling capex, because an abandonment cost is not capex in a screening case.", "It moves the line back to ABEX, because the engine reads the description of a provision before it totals the items by type.", "It adds the line to the CAPEX total without a murmur, because a cost item''s type is a field somebody chose.", "It leaves the CAPEX total at 2250.0000 and raises a warning, since the Operate phase roll-up of 355.0000 already carries the line."]'::jsonb, 2, 'The engine will not classify a line for you: it totals what the types say, so a provision typed as CAPEX lands in the capex the economics run on.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 5, 'A reviewer adds the decommissioning provision of 260.0000 to the capex to be conservative. What is wrong with the figure that results?', '["The arithmetic holds, but the screening case then charges the provision twice, once inside the capex and once in the Operate phase roll-up of 355.0000.", "The provision would have to be grown to the end of the 20.0000 year life first.", "The engine refuses a capex it did not read from the cost items itself.", "It matches nothing: the engine reports CAPEX 2250.0000, and the new number agrees with no concept estimate."]'::jsonb, 3, 'Abandonment belongs in a tier that models it with a year and a fiscal treatment; in a screening case the capex is 2250.0000 and a hand altered figure reconciles against nothing.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 6, 'Across the Base case the operating cost totals 3049.6464 million USD, well above the 1900.0000 that 95.0000 a year over 20.0000 years gives. What is the difference?', '["The decommissioning provision of 260.0000 and the maintenance and integrity line of 23.0000, which the engine adds to the operating cost across the life.", "The variable charge of 5.0000 USD on every barrel produced, which the fixed OPEX total does not carry.", "The escalation the engine applies to the fixed 95.0000 through the 21 rows.", "The royalty of 12.5000 percent, charged inside the operating cost line."]'::jsonb, 1, 'The OPEX total of 95.0000 is the fixed part only, so year 1 charges 204.5000 on a full plateau and year 4 charges 193.5500, and the difference across the life is the barrels.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 7, 'A three year production profile is run against a price deck that holds two prices. What does the engine return?', '["A refusal naming the year, that the deck has no price for production year 3 and every year of the profile wants one.", "The NPV of -202.4284 the three price deck returns, the last price being carried into the year the deck misses.", "An NPV of 126.1636 and no rate of return, the missing year having been valued at zero.", "A warning on the card and a value built on the two years priced."]'::jsonb, 0, 'The same profile with three prices is accepted and returns -202.4284, and nothing about the field changed between the two attempts.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 8, 'A scenario priced at 0 returns an NPV of -3517.4133 million USD, while a deck missing one year''s price is refused outright. Why are the two treated differently?', '["Zero sits inside the band of prices the engine accepts and a missing year sits outside it, in the way a price of -5 sits outside it.", "A zero priced barrel is valued at the default of 70.0000 USD a barrel, and the engine has no default to reach for when a year is absent.", "A typed zero is the question somebody asked; a missing year is a question nobody asked, and answering it invents the input and the output together.", "A scenario carries one price while a deck carries many, and the engine refuses any deck holding more than one price for a profile."]'::jsonb, 2, 'Zero is a number somebody chose and the engine owes them its answer of -3517.4133; the missing year gets a refusal in place of a price nobody supplied.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 9, 'A published case runs a deck shorter than its profile with the missing prices treated as zero, and returns an NPV of 126.1636 with no rate of return. What does that case show?', '["That a short deck is safe so long as the missing years are valued at zero, since the case still returns a value and only the rate is withheld.", "That padding is invisible in the result: the value reads ordinary while the tail is worth nothing and the flow changes sign more than once.", "That the engine pads a short deck with zero and reports the status multiple-roots as its way of saying that it has done so.", "That a rate of return is withheld whenever the value is small, and 126.1636 falls below the figure at which the engine reports a rate."]'::jsonb, 1, 'One caller padded the missing years with 70.0000 USD a barrel and another with zero, so one plan gave two answers, and neither path said a price had been supplied.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 10, 'How do the four drivers of the sweep rank by what each does to the value of the plan''s own case?', '["Oil price at 3092.0051, production at 2839.5965, capex at 1287.1745, then operating cost at 323.8828.", "Capex at 1287.1745 first, as the one driver the plan controls, then oil price, production and operating cost behind it.", "Production at 2839.5965 first and oil price at 3092.0051 second, because barrels earn the revenue and the deck only prices them.", "Operating cost at 323.8828 first, as the only driver charged in all of the 21 rows, then capex, production and oil price."]'::jsonb, 0, 'Ranked by swing the order is oil price, production, capex and operating cost, and the driver at the top moves the value by nearly ten times what the one at the bottom does.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 11, 'The oil price swing is 3092.0051 and the production swing is 2839.5965, although both drivers scale revenue. What makes the price swing the larger of the two?', '["The royalty of 12.5000 percent is charged on the price and not on the volume, so a move in the deck reaches the net cash flow untouched by it.", "Production is moved by 30 percent on the plateau of 60.0000 kbpd alone, while the price is moved by 30 percent in every one of the 21 rows.", "The capex of 2250.0000 is sized from the peak rate, so more barrels bring more spend with them and cancel part of the revenue they earn.", "A barrel carries a variable operating cost of 5.0000 USD and a dollar of price carries none."]'::jsonb, 3, '30 percent more barrels brings 30 percent more revenue and more cost with it, so price is the stronger driver wherever barrels cost money to lift.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 12, 'The capex row of the sweep reads 2691.1526 at minus 30 percent and 1403.9781 at plus 30 percent. What is a reader who expects every bar to grow to the right about to report?', '["That the capex swing of 1287.1745 is the largest of the four, because the bar drawn from 1403.9781 to 2691.1526 is the widest on the chart.", "That the base value of 2047.5653 falls outside the capex range, because the two capex figures sit either side of it in the wrong order.", "That overspending improves the plan, having read the sign of the capex sensitivity backwards.", "That an overrun of 30 percent is worth 2691.1526."]'::jsonb, 2, 'More capex is less value, so the capex row reads high on the left and low on the right, and an overrun of 30 percent takes the case from 2047.5653 to 1403.9781.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 13, 'Someone labels the plus 30 percent column of the sweep a P10 case and the minus 30 percent column a P90 case. What is wrong with those labels?', '["The sweep holds no distribution: it moves one driver by 30 percent and says nothing about how likely that move is.", "They are the wrong way round, because more of a driver is the low case and the label belongs on the column reading 3593.5679.", "They belong to the plan as a whole, so only the base value of 2047.5653 may carry one of them.", "They may be used on the oil price row, whose swing of 3092.0051 was measured across prices, but not on the other three."]'::jsonb, 0, 'A P-label belongs to a reserves distribution, one fluid at a time, and 30 percent on the oil price and 30 percent on the operating cost are not equally likely events.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 14, 'A plan that scores 100 percent complete has its economics section emptied. What does the studio report for it then?', '["A value of zero and 100 percent complete, because the other eight sections still carry what they carried and the check counts sections.", "89 percent complete, with one named error, that total CAPEX is zero or missing.", "0 percent complete and three errors, naming the project name, the reserves estimate and the total capex, as an empty plan does.", "89 percent complete and no error at all, because the economics fall back to the concept whenever the plan''s own cost items are absent."]'::jsonb, 1, 'One section emptied gives one error and a score of 89 percent, and the studio answers with a list of what is missing rather than with a number.'),
  ('fdp', 'beginner', 'module', 'm05-the-plan-s-own-economics', 15, 'One plan carries a negative value in its economics and another carries a value of exactly zero. How does the completeness check read the two?', '["Both count as economics done, because the check asks only whether a figure was written into the section at all.", "Neither counts, because the check wants a value above zero and both fail the error that total CAPEX is zero or missing.", "The negative value counts as economics done at 11 percent, while the zero scores 0 percent, because a calculated zero cannot be told from an empty field.", "The zero counts and the negative does not, because a negative value fails validation and the section reads as not yet estimated."]'::jsonb, 2, 'A negative value scores 11 percent on an otherwise empty record and a value of exactly zero scores 0 percent, which is a property of the check as published.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 1, 'A slide reports the field''s reserves as 200.0000 and the FPSO concept''s capex as 1350.0000 million USD. Which two rules were broken?', '["The reserves were summed at P50 where a screening slide wants the low case, and the capex was taken from the cost items rather than from the concept record.", "The reserves were quoted without their recovery factors, and the capex before drilling was estimated.", "Oil and gas were added across their units, and the capex was read from the facilities field alone.", "The reserves were rounded before they were added, and the capex quoted in the wrong unit."]'::jsonb, 2, 'Oil is 130.0000 MMbbl and gas is 70.0000 Bcf, which never add, and the concept''s capex is 520.0000, 1350.0000 and 380.0000 read together as 2250.0000.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 2, 'A reader sets the FPSO''s 2047.5653 beside the tie-back''s 1048.6281, and the oil P50 of 130.0000 beside the gas P50 of 70.0000. Which comparison stands?', '["The two values, because both are million USD on the same field at 70.0000 USD a barrel, while the two reserves figures are different fluids in different units.", "The two reserves figures, because both come from one plan through one accessor, while the values were run on concepts of different capex, life and peak rate.", "Both of them, because each pair is drawn from a single plan and the studio prints the members of a pair beside each other on the same card.", "Neither of them, because the values sit on capex of 2250.0000 and 730.0000 and the reserves sit in MMbbl and Bcf."]'::jsonb, 0, 'Two values at one price are comparable, and the differences between the concepts are what the comparison is about; 130.0000 MMbbl and 70.0000 Bcf are not comparable at all.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 3, 'A question asks for the plan''s annual operating cost and the answer given is 3049.6464. What has been answered instead?', '["The cost of one plateau year, which the case charges at 204.5000 once the variable part is added to the fixed part of it.", "The operating cost across the whole Base case, where the annual figure is 95.0000 a year.", "The Operate phase roll-up of 355.0000 restated across the life, carrying the decommissioning provision of 260.0000 inside it.", "The concept''s fixed cost over its 20.0000 year life of 1900.0000."]'::jsonb, 1, '3049.6464 is the life total the Base case charges, above the 1900.0000 that 95.0000 a year gives, and half the wrong answers in this subject are right answers to a different question.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 4, 'A question gives a concept''s drilling, facilities and subsea figures and asks for its capex. What is the method?', '["Read the single total capex field the concept record holds, which somebody fills in once the three estimates have been added by hand.", "Read the CAPEX total of the plan''s cost items, which the engine copies onto the concept.", "Take the facilities figure and gross it up for the rest of the work.", "Add the three fields the concept carries, as 520.0000, 1350.0000 and 380.0000 give 2250.0000."]'::jsonb, 3, 'The engine reads all three fields, and a capex read from a field the form never wrote is confidently wrong however plausible it looks.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What production profile does a concept imply in the screening tier?', '["A reservoir forecast built from the recovery factor each reservoir row carries, which is why a profile and the reserves behind it always agree.", "A plateau at its peak rate and then a decline of 0.900000 a year, dated from the concept''s own start.", "A flat rate at the peak of 60.0000 kbpd across the whole 20.0000 year life.", "A decline from the first year at 0.900000, with no plateau at all."]'::jsonb, 1, 'The FPSO concept holds 60.0000 kbpd to year 3 and then declines by 0.900000 a year, and the result is a screening curve rather than a reservoir forecast.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 6, 'An NPV of 2047.5653 million USD is carried out of the studio with no conditions attached to it. What has been left behind?', '["Nothing, because a value is always stated after royalty and tax on the studio''s default terms and so carries its own conditions wherever it goes.", "The reserves the value was earned on, because 130.0000 MMbbl of oil and 70.0000 Bcf of gas are what the case sold to reach 2047.5653.", "The price of 70.0000 USD a barrel, the capex of 2250.0000, the operating cost of 95.0000 a year, the royalty of 12.5000 percent, the tax of 30.0000 percent, the discount rate of 10.0000 percent and the 20 year shape.", "The rate of return of 29.5998 percent and the payback of 3.8273 years, without which a value carries no measure of timing beside it."]'::jsonb, 2, 'Every value in this course is conditional on something, and the same concept at 18.0000 USD a barrel returns -1797.2732 with nothing else changed.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 7, 'The Base case reports 2047.5653, 29.5998 and 3.8273. What kind of quantity is each of the three?', '["Money in million USD, then a percent, then a duration in years.", "Money in million USD, a percent, and a second percent, because payback states the share of the life that has been recovered.", "Money in whole currency units, a plain ratio, and a duration in years counted from the sanction date of the concept.", "Money in million USD, a plain ratio of the kind 1.436477 is, and a duration in years."]'::jsonb, 0, 'Plan money prints in million USD, a rate of return is the percent 29.5998, and payback is 3.8273 years, so the unit written beside each figure makes a unit error visible.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 8, 'The tie-back concept returns 1.436477 at 70.0000 USD a barrel. In what unit is that figure?', '["Percent, the rate of return the tie-back earns on the capex of 730.0000 it asks for across its life of 15.0000 years.", "A plain number, the value earned for each million USD of capex.", "Million USD, the value left once the capex has been taken out of the NPV of 1048.6281 the concept reports.", "MMbbl, the barrels the tie-back recovers for each million USD it spends over its 15.0000 year life."]'::jsonb, 1, 'A ratio is a plain number and a rate of return is a percent, so 1.436477 and the 40.4321 percent the tie-back earns are different animals.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Why do the FPSO concept and the subsea tie-back differ so much in what they cost and what they earn?', '["The FPSO is priced at 70.0000 USD a barrel while the tie-back is screened at the lower price that its shorter life of 15.0000 years implies.", "The FPSO is allotted the field''s oil P50 of 130.0000 MMbbl while the tie-back is allotted the gas P50 of 70.0000 Bcf to produce.", "The FPSO pays the royalty of 12.5000 percent and the tax of 30.0000 percent, from which a tie-back of that size is exempt.", "The FPSO carries capex of 2250.0000, a peak of 60.0000 kbpd and 20.0000 years against 730.0000, 25.0000 kbpd and 15.0000 years."]'::jsonb, 3, 'Both rows run at 70.0000 USD a barrel on one set of terms, so the only differences are the capex, the operating cost, the peak rate and the life each concept carries.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What does the studio answer with when it cannot produce a number?', '["A refusal naming the missing input, a payback of never, and a rate of return given as a status.", "A value built on the studio''s defaults, with a warning on the card naming each figure that was substituted for the plan''s own.", "A zero in the field it cannot fill, since a zero is the neutral entry and lets the rest of the calculation go through.", "The last value the plan reported before the input went missing."]'::jsonb, 0, 'A missing price is refused by name, a case that never recovers its capex reports never, and a rate that does not exist reports its status instead of a figure.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 11, 'This course carries a development plan priced in million USD and a project schedule priced in whole currency units. What follows from that?', '["The two can be compared once the plan money is multiplied out, because a million USD figure and a whole currency figure are one scale restated.", "The schedule is the smaller model, its costs being printed without decimals.", "A figure borrowed from one of them and used in the other is wrong even when it looks plausible.", "Plan money should be restated in whole currency units before any arithmetic."]'::jsonb, 2, 'The models share nothing, and the unit beside a figure is the first thing to check: plan money prints as million USD to four decimals.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What does rounding a figure as you work, rather than at the end, do to an answer?', '["Nothing at all, because the studio rounds every input before it runs.", "It is the safer practice, because a rounded input cannot carry more precision than the estimate behind it was entitled to claim.", "It changes the unit of the answer, because a figure rounded to whole numbers leaves the million USD scale for a whole currency one.", "It puts an error in the final line that nothing later in the work can find."]'::jsonb, 3, 'Carry the figures at the precision they were printed at, such as 2047.5653 and 0.330657, do the arithmetic once, and quote at the precision the question asks for.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What does a field development plan hold in this studio?', '["One concept worked through in full, the alternatives being kept in plans of their own with their own reserves.", "One field: its reserves, its concepts, the wells and facilities those imply, a schedule, a cost breakdown, a risk register and the economics.", "The subsurface model and the well designs themselves, which the studio derives and holds beside the schedule.", "The economics alone, the reserves and the facilities staying in the applications that produced them."]'::jsonb, 1, 'The plan is one field and the studio holds those parts together, re-deriving none of them.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 14, 'A graded question fixes a price and asks what a concept is worth. What is written down first?', '["The formula for a discounted cash flow, so that the arithmetic is laid out before any of the plan''s own figures are looked up.", "The value the same concept reported in the lesson, which gives a figure to check the working against once the arithmetic is done.", "What the question fixes and what has to be read out of the plan.", "Every figure the plan carries, in the order the card prints them, so that nothing in the record is left out of the working."]'::jsonb, 2, 'A graded question is won or lost in the minute spent deciding which number is wanted and what it is measured in, before any arithmetic happens.'),
  ('fdp', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does the Associate tier hand on to the rest of the course?', '["That a number comes from the field it was typed in, that units travel with their figures, and that an engine which cannot answer says so.", "A set of values to carry forward, led by the 2047.5653 the Base case reports, against which the later work is checked.", "The default terms of 12.5000 percent royalty and 30.0000 percent tax, which every later tier reuses unchanged.", "The completeness score of 100 percent, which the later tiers raise as each further section is filled in."]'::jsonb, 0, 'The habits carry forward: a figure typed into the studio is only as good as the work behind it, and a refusal is an answer.'),
  ('fdp', 'beginner', 'final', null, 1, 'The EGINA plan reads completeness 100 percent on 9 of 9 sections. Take its economics section out and leave everything else alone. What does the studio then report?', '["0 percent and no error, because a plan the studio cannot cost is scored as an empty record until a capex is typed back into it.", "100 percent still, because the other eight sections are untouched and the economics section is scored off the concept''s own capex of 2250.0000 million USD rather than off its own box.", "89 percent, with the error \"Total CAPEX is zero or missing.\", because one of the nine stops carrying a figure and the check names what went with it.", "89 percent with an empty error list, because the count of sections carrying something is the whole of the score and the error list is reserved for the reserves check alone."]'::jsonb, 2, 'One section emptied moves the score by roughly a ninth, from 100 percent to 89 percent, and the error names the missing capex rather than the section it came from.'),
  ('fdp', 'beginner', 'final', null, 2, 'The studio shows three figures for what this development costs: concept capex 2250.0000, cost items CAPEX 2250.0000 and 1363.3524 million USD. What is the third of them?', '["A class 5 screening estimate drawn from the facility type and its 60000 bopd nameplate, covering the Egina FPSO alone and none of the drilling or the subsea.", "The facilities part of the concept read back through the cost breakdown, which is why it sits below the concept''s own facilities capex field of 1350.0000 million USD.", "A costed number for the vessel built from the seven cost items, which is why it prints to four decimals like the 2250.0000 beside it.", "The lowest of three quotes for the same scope, carried so that a reader can see the range the 2250.0000 estimate was drawn from."]'::jsonb, 0, 'The 1363.3524 million USD comes from a type and a nameplate and the 2250.0000 of cost items comes from seven lines somebody wrote; both print to four decimals and neither is the same class of number.'),
  ('fdp', 'beginner', 'final', null, 3, 'The plan''s cost items put 520.0000 into Execution, 1180.0000 into Construction and 550.0000 into Installation, while the FPSO concept carries drilling 520.0000, facilities 1350.0000 and subsea 380.0000. How do those two cuts line up?', '["They do not line up: the Installation phase of 550.0000 million USD has no counterpart in the concept record, which carries the mooring inside its drilling field of 520.0000 instead.", "They cut the same 2250.0000 million USD two ways: drilling is Execution, the concept''s facilities figure is the hull and topsides of 1180.0000 plus the mooring of 170.0000, and its subsea figure is the subsea system line of 380.0000.", "The four phases are the three capex fields with one added, so Execution is the drilling, Construction is the facilities, Installation is the subsea and Operate is the 95.0000 million USD a year the concept carries, which is how the four phase figures and the three capex fields both come to total 2250.0000 million USD.", "The concept fields were rolled up from the phases, which is why both reach 2250.0000 million USD, and the studio refuses to price a plan whose roll-up and concept record disagree, naming the phase whose total has moved away from the capex field it was rolled up into."]'::jsonb, 1, '1180.0000 plus 170.0000 is the concept''s facilities capex of 1350.0000 and the subsea system line is its subsea capex of 380.0000, so the same money is being cut by what it buys and by when it leaves.'),
  ('fdp', 'beginner', 'final', null, 4, '"the drilling capex may not be negative: -500" does something that "the scenario oil price is missing" cannot. What, and why is it worth having?', '["It names a field somebody filled in rather than a field left empty, so it alone carries a FdpInputError while the missing price returns a warning the run continues past.", "It carries the cell reference beside the value, and that reference rather than the value is what lets a reader find the box, which a missing price has no way to supply.", "It stops the whole plan rather than the one scenario, because a value that cannot be read might already have reached any other calculation the studio had run.", "It quotes the offending value back, so -500 is searchable in the plan, and a figure nobody entered has no value to quote."]'::jsonb, 3, 'Five of the ten published refusals quote the value back, -500, -5, abc, x and lots, and every one of the ten is a FdpInputError that names its own field.'),
  ('fdp', 'beginner', 'final', null, 5, 'A board paper prints the Low price, Base and High price scenarios as the range the field could be worth, 427.9436 to 3667.1870 million USD. What has the paper claimed that the tier does not?', '["That the three describe a spread: each is a separate run of one concept conditional on the single price typed at its head, and the tier holds no view on how likely 48.0000 or 92.0000 USD a barrel is.", "That the three share one concept, when the Low price row runs the subsea tie-back on its own capex of 730.0000 million USD and only the Base and the High price figures sit on one scale, so the range the paper prints is two concepts wide rather than one.", "That the figures are comparable, when each row is discounted at a rate matched to its own price and only the Base case runs at the default 10.0000 percent.", "That the studio named them, when Low price, Base and High price are the engine''s own judgements about which of the three prices is conservative and which optimistic."]'::jsonb, 0, 'Four rows of one concept at four typed prices are four complete answers, not a distribution, and the tier will not say whether any of the prices is plausible.'),
  ('fdp', 'beginner', 'final', null, 6, 'Quoting an NPV of 2047.5653 million USD without its terms is quoting half a number. Which set of defaults is that value conditional on?', '["Royalty 12.5000 percent, tax 30.0000 percent, a discount rate of 10.0000 percent and the concept''s fixed operating cost of 95.0000 million USD a year, discounted at each year end.", "An oil price of 70.0000 USD a barrel, a peak rate of 60.0000 kbpd, a life of 20.0000 years and a capex of 2250.0000 million USD.", "Royalty 12.5000 percent, tax 30.0000 percent, a discount rate of 10.0000 percent and a variable operating cost of 5.0000 USD a barrel, discounted mid year.", "Royalty 12.5000 percent, tax 30.0000 percent, a discount rate of 10.0000 percent and an abandonment provision of 260.0000 million USD."]'::jsonb, 2, 'The four stated defaults are royalty 12.5000 percent, tax 30.0000 percent, discount 10.0000 percent and a variable operating cost of 5.0000 USD a barrel, and the discounting is mid year.'),
  ('fdp', 'beginner', 'final', null, 7, 'EGINA''s oil P50 of 130.0000 MMbbl comes off the reserves table. Which rows is it built from, and what does the recovery factor column contribute?', '["Egina Main at 95.0000 and Egina Deep at 35.0000, each weighted by its recovery factor of 0.340000 and 0.280000 before they are added.", "Egina Main at 95.0000 and Egina Deep at 35.0000, and the recovery factor contributes nothing: the engine adds the percentile columns and never touches it.", "All three reservoir rows at P50, with the Egina Gas Cap''s 70.0000 Bcf converted to a barrel of oil equivalent basis first and each row''s recovery factor carried through that conversion.", "Egina Main at 95.0000 on its own, because Egina Deep''s recovery factor of 0.280000 falls below the field average and the engine reports that reservoir as a second oil line."]'::jsonb, 1, '95.0000 plus 35.0000 is 130.0000 MMbbl, and the recovery factor is context for the volume rather than an input to the sum.'),
  ('fdp', 'beginner', 'final', null, 8, 'A reserves row named Aquifer is typed with a fluid of Brine. What comes back, and what would be different if the row had no name?', '["\"Aquifer: fluid type is missing or unknown (Brine); expected one of Oil, Gas, Condensate\", and an unnamed row is refused by its position instead, as row 2.", "Brine is reported as a fluid the engine does not price and the row is dropped from the totals, and an unnamed row is dropped the same way under a warning that the table holds fewer rows.", "The message lists Oil, Gas, Condensate and Water as the fluids the engine knows, and a row with no name is given the name Unlabelled.", "The whole table is refused rather than the row, so the plan reports P50 0.0000 and completeness 89 percent until the fluid is fixed."]'::jsonb, 0, 'The message uses the name somebody typed, which is why Aquifer and Unlabelled are names in the table, and an unnamed row comes back as "row 2: fluid type is missing or unknown (undefined)".'),
  ('fdp', 'beginner', 'final', null, 9, 'Two of the studio''s totals turn on a type somebody picked from a list: the fluid on a reserves row and the cost type on a cost item. What does the engine do with an entry it cannot use in each of them?', '["It refuses both by name, so a provision typed as CAPEX comes back the way a fluid typed as Brine does, naming the item and quoting the type that was entered, so that the reader can find the cell that holds it and correct it there.", "It accepts both and reports them apart, opening a column of its own for an unknown fluid and holding an unknown cost type outside the CAPEX and OPEX totals the way an ABEX line is held.", "It drops the reserves row from the totals under a warning and refuses the cost item, because a volume can be summed with one row missing and a money total cannot.", "It refuses the reserves row by name, because a fluid it cannot read has no column to sit in, and it accepts whatever a cost item''s type says, so a decommissioning provision typed as CAPEX is totalled into the capex."]'::jsonb, 3, 'A row typed as Brine returns "Aquifer: fluid type is missing or unknown (Brine); expected one of Oil, Gas, Condensate", while the engine will not classify a cost line for you and totals what the type field says.'),
  ('fdp', 'beginner', 'final', null, 10, 'The sweep prices the plan''s case with CAPEX at minus 30 percent, 2691.1526, and at plus 30 percent, 1403.9781. What is wrong with calling those the P90 and the P10 capex?', '["The labels are right only for a driver that lifts the value, so a capex row reads P10 at minus 30 percent and P90 at plus 30 percent.", "A capex may carry a P-label once the sweep has been run at more than the two points, because three or more runs describe enough of a spread for a percentile to be read off them.", "A P-label belongs to a reserves distribution, one fluid at a time, and the sweep holds no distribution: it moves a driver by 30 percent and says nothing about how likely that is.", "The sweep moves all four drivers at once in each run, so neither figure belongs to the capex alone and no percentile of any kind could be attached to either of the two columns."]'::jsonb, 2, 'P90 is the low case of a reserves distribution, such as the oil P90 of 80.0000 MMbbl, while 2691.1526 is one driver moved 30 percent with the other three held at the base case.'),
  ('fdp', 'beginner', 'final', null, 11, 'The engine returns an OOIP of 403539180.4580 STB for an Egina Main zone, which is 403.5392 MMstb. What makes quoting that as the field size expensive?', '["The zone covers 2400.0000 acres of a larger field, so the figure understates what is in place and a reader who quotes it is low rather than high, which is the safer of the two errors.", "An in place volume becomes reserves only after a recovery factor, and the plan''s recoverable oil is 130.0000 MMbbl, so the listener hears a field several times the size of the one being developed.", "The four decimals on 403539180.4580 STB describe the arithmetic rather than the mapping, so the fault is in the precision quoted and not in the quantity the figure describes.", "Oil in place is carried in stock tank barrels and reserves in MMbbl, so the two are not comparable until the formation volume factor of 1.310000 has been applied to the volume a second time."]'::jsonb, 1, '403.5392 MMstb is oil in place and 130.0000 MMbbl is what the plan expects to recover from it, an implied recovery factor of 0.322150.'),
  ('fdp', 'beginner', 'final', null, 12, 'A reserves figure can reach a plan three ways: a headline somebody typed, a summary carried in from a loaded example, and a table of reservoir rows. Which of the three is the plan''s own P50?', '["The headline, because it is the figure the generated document prints beside the total CAPEX of 2250.0000 million USD and the NPV of 2047.5653, and the only one a reader of the finished plan ever sees.", "The summary, because a plan carrying one scores 33 percent with isValid true while a plan carrying the rows alone scores 78 percent and fails validation until somebody has filled the summary box in behind them.", "Whichever of the three the plan carries first, because the accessor reads them in that order and stops at the first figure it can resolve.", "The table, because the engine totals the rows one fluid at a time and the completeness check, the generated document and the economics all reach the reserves through that one accessor."]'::jsonb, 3, 'A headline typed by hand, a summary carried in from an example and a table of rows can all sit in one plan and disagree, and the number that belongs to the plan is the one totalled from the rows.'),
  ('fdp', 'beginner', 'final', null, 13, 'At 12 MMbbl a well the engine returns 11 wells for the oil P50 of 130.0000 MMbbl, and the plan carries 4 wells. What should a reader do with the two figures?', '["Read them as real answers to different questions, one a drainage assumption applied to the recoverable volume and one the well list as it stands, and go and reconcile them, because the studio will not.", "Take the 4, because the well list holds a designed trajectory for each well while the 11 is a screening figure the engine drew from the concept''s peak rate and its life.", "Take the 11, because the completeness check reads a plan''s well count from its reserves and a plan carrying only 4 fails validation until the list has caught up with the volume.", "Average the two, because 12 MMbbl a well is an assumption at one end and a well list is an intention at the other, so the plan''s true count sits somewhere between them."]'::jsonb, 0, '11 wells is what 130.0000 MMbbl needs at an assumed 12 MMbbl a well and 4 is what the well list holds, and nothing in the studio resolves the gap between them.'),
  ('fdp', 'beginner', 'final', null, 14, 'The gas total reads 70.0000 Bcf on a row count of 1. Why does that row count matter as much as the total beside it?', '["A count of 1 means the engine could not aggregate the distributions it was given, so the gas figure is a sum of low cases in the way the oil column of 80.0000 MMbbl is.", "The count decides the unit: one gas row stays in Bcf, while two or more would be totalled onto a barrel of oil equivalent basis.", "A fluid with one row has no aggregation in it, so 70.0000 Bcf is a single reservoir estimate carried through rather than a sum of anything.", "A count of 1 marks the fluid as unverified, because the engine will not label a column P50 until it has at least two independent estimates of the same volume to read it from."]'::jsonb, 2, 'The oil P50 of 130.0000 MMbbl is two rows added and the gas P50 of 70.0000 Bcf is one row carried through, and the row count is what tells the two apart.'),
  ('fdp', 'beginner', 'final', null, 15, 'Which of the figures on the FPSO concept record did the studio work out for itself?', '["The operating cost of 95.0000 million USD a year, which the engine sizes from the vessel''s nameplate of 60000 bopd, and the 36 months, which it takes from the concept type and holds against the sanction date of 2027-04-01.", "None of them: the capex fields, the operating cost, the peak rate and the life were all typed in, and even the 36 months to first oil is a duration the concept type carries rather than an estimate the studio made.", "The peak rate of 60.0000 kbpd and the life of 20.0000 years, which the engine reads back off the oil P50 of 130.0000 MMbbl so that the shape it draws can be fed by the reserves.", "All of them, because a concept record is generated from the concept type and the field''s reserves, which is why two concepts on one field carry different capex, peak rate and life."]'::jsonb, 1, 'The studio holds a plan together and re-derives nothing in it, so a concept figure is only as good as the work behind it and a duration attached to a type deserves the same scrutiny as any other entry.'),
  ('fdp', 'beginner', 'final', null, 16, 'The FPSO concept''s lifecycle cost is 4150.0000 million USD. What is inside that figure, and what is not?', '["Capex of 2250.0000 plus the whole case operating cost of 3049.6464, which carries the variable 5.0000 USD a barrel with it, and the 260.0000 decommissioning provision charged at the end of the life.", "Capex of 2250.0000 plus 1900.0000 of operating cost discounted at 10.0000 percent, which is what lets it be set beside the NPV of 2047.5653 million USD as a figure on the same scale.", "The cost items'' CAPEX of 2250.0000 plus the Operate phase roll-up of 355.0000 taken across the life, which is the route by which the decommissioning provision enters the lifecycle figure.", "Capex of 2250.0000 plus 1900.0000 of operating cost, undiscounted, and the 260.0000 decommissioning provision is not in it."]'::jsonb, 3, '95.0000 a year across 20.0000 years is 1900.0000, and 2250.0000 plus 1900.0000 is 4150.0000, a plain sum with no discounting and no abandonment inside it.'),
  ('fdp', 'beginner', 'final', null, 17, 'The FPSO concept''s profile reads 60.0000, 60.0000, 60.0000, 54.0000, 48.6000 and 43.7400 kbpd. Which two inputs drew the whole of that curve?', '["The peak rate of 60.0000 kbpd, which sets the height, and the life of 20.0000 years, which sets how long the decline of 0.900000 a year runs for.", "The oil P50 of 130.0000 MMbbl, which fixes the area under the curve, and the life of 20.0000 years, across which the engine spreads that recoverable volume year by year.", "The peak rate of 60.0000 kbpd and the well count of 4, since each well carries its own share of the plateau.", "The peak rate of 60.0000 kbpd and the concept''s 36 months from sanction to first oil, which is what holds the plateau at three years before the decline is allowed to start."]'::jsonb, 0, 'The plateau runs to year 3 and year 4 is year 3 times 0.900000, which is 54.0000 kbpd, and nothing about the rock, the wells or the reserves enters the shape at all.'),
  ('fdp', 'beginner', 'final', null, 18, 'The volume under the FPSO concept''s 20 year shape is 229.9293 MMbbl and the plan''s oil P50 is 130.0000 MMbbl. What does the studio do about the difference?', '["Caps the profile at the recoverable volume, so the decline steepens once cumulative production reaches 130.0000 MMbbl.", "Nothing: the shape is drawn from a peak rate and a life without consulting the reserves, so the plan still scores complete and still returns 2047.5653 million USD.", "Refuses the scenario by name, as it refuses a price deck that does not cover the profile, and asks for a larger reserves figure.", "Reports the difference as a warning against the completeness check, which is why a plan built this way reads 89 percent rather than the 100 percent its nine sections would otherwise give."]'::jsonb, 1, '229.9293 MMbbl under a shape drawn from two inputs against 130.0000 MMbbl in the reserves table, and the reconciliation is the planner''s job rather than the engine''s.'),
  ('fdp', 'beginner', 'final', null, 19, 'An FPSO sanctioned on 2028-02-29 reaches first oil on 2031-03-01, and one sanctioned on 2027-04-01 reaches it on 2030-04-01. What do the two say about how a concept is dated?', '["The engine counts 36 months as calendar days from the start date, which is what puts a leap day start one day later than plain month arithmetic would have placed it.", "The engine dates a concept off the plan''s sanction milestone, so both inherit the schedule''s 870 day network and differ only in their start.", "The engine adds 36 whole months to the start date somebody typed and lands on a date that exists, and it reads no clock, so the answer is the same on any machine on any day.", "The engine dates from today unless a start date is given, so a concept carrying 2028-02-29 is anchored and one without a date moves."]'::jsonb, 2, '36 months from 2027-04-01 is 2030-04-01 and 36 months from 2028-02-29 is 2031-03-01, and a concept with no start date and no today supplied is refused rather than dated from a clock.'),
  ('fdp', 'beginner', 'final', null, 20, 'Both EGINA concepts are sanctioned on 2027-04-01 and the tie-back reaches first oil a full year before the FPSO. Where does that year come from?', '["The capex each concept carries, so the tie-back''s 730.0000 million USD buys a shorter build than the FPSO''s 2250.0000 does, and the months move with the money committed.", "The network of eight activities, whose critical path of 870 days is walked once for each concept and cut short for the tie-back by the work that concept does not have to do.", "The peak rate: the tie-back''s 25.0000 kbpd needs fewer wells than the FPSO''s 60.0000 kbpd, and the 24 and the 36 months are measuring those two drilling campaigns.", "The concept type: 24 months for a tie-back hung off a host already there, 36 for an FPSO whose hull must be converted."]'::jsonb, 3, 'A Platform sanctioned on 2027-04-01 also reaches first oil in 24 months, so the duration belongs to the concept type rather than to the size of the spend.'),
  ('fdp', 'beginner', 'final', null, 21, 'The Low price scenario runs the FPSO at 48.0000 USD a barrel for an NPV of 427.9436 million USD, and the sweep''s oil price at minus 30 percent returns 501.5628. Why do two low price answers on one concept disagree?', '["The sweep prices the plan''s own case off the cost items while the scenario prices the concept, so the 501.5628 runs on a capex that the 427.9436 does not.", "They are not at the same price: 30 percent off the base of 70.0000 USD a barrel is 49.0000, and the scenario was typed at 48.0000.", "The scenario carries a full deck at 48.0000 while the sweep moves the producing years only, leaving year 0 priced at the base of 70.0000 USD a barrel.", "The sweep reports a swing rather than a value, so 501.5628 is the distance the value moved and not what the case is worth at the lower price."]'::jsonb, 1, 'Both runs use the same 2250.0000 million USD of capex, the same 20 year shape and the same terms, so a dollar of price is the whole of the difference between 427.9436 and 501.5628.'),
  ('fdp', 'beginner', 'final', null, 22, 'The FPSO pays back in 3.8273 years and the tie-back at the same price in 3.2035. Which does a payback ranking choose, and what does that ranking miss?', '["The tie-back, and the ranking misses that the FPSO is worth 2047.5653 million USD against the tie-back''s 1048.6281, because payback stops counting at the crossing.", "The FPSO, because a longer payback across a life of 20.0000 years is the stronger result, and the ranking misses the 15.0000 year life.", "The tie-back, and the ranking misses nothing, because a rate of return of 40.4321 percent against 29.5998 puts it first on both measures.", "Neither, because payback carries no discount rate of its own and only shows the year the capex of 2250.0000 is recovered in cash."]'::jsonb, 0, 'Payback ranks the tie-back first at 3.2035 years and value takes the FPSO at 2047.5653 million USD, because the years after the crossing reach the NPV and never reach the payback.'),
  ('fdp', 'beginner', 'final', null, 23, 'A worked answer calls the payback of 3.8273 years the point at which the Base case has recovered its 2250.0000 million USD in present value terms. What is wrong with that sentence?', '["Nothing is wrong with it, since payback and value are measured on one discounted flow and 3.8273 years is simply where that flow first turns positive at the 10.0000 percent the scenario carries.", "The capex is wrong rather than the discounting, because payback is measured against the cost items'' CAPEX total and the 2250.0000 million USD quoted is the concept''s own estimate, and the two agree on this plan only because it was costed against the concept it runs.", "Payback carries no discount rate of its own: it is where the plain cumulative cash position crosses zero, and the 10.0000 percent taken mid year belongs to the 2047.5653 million USD instead.", "Payback is measured after the state is paid while the 2250.0000 million USD is a gross figure, so the sentence sets a post take measure against a pre take one."]'::jsonb, 2, 'The cumulative runs -2250.0000, -1454.1875, -658.3750 then 137.4375 with nothing discounted, and payback is placed inside the year where that crossing happens.'),
  ('fdp', 'beginner', 'final', null, 24, 'At 40.0000, 55.0000, 70.0000 and 85.0000 USD a barrel the same concept returns -161.0098, 943.2778, 2047.5653 and 3151.8529. Why is the step even?', '["The engine interpolates between the two prices it was given a full run at, so the two middle figures are read off a straight line drawn between 40.0000 and 85.0000 USD a barrel.", "Royalty and tax are charged on what is left after costs, so the state absorbs the curvature in the cash flow and leaves the value rising evenly with each step in the price.", "The four prices are evenly spaced within one price deck, and a deck that covers every year of the profile always returns an even step in the value it prices out.", "Only what a barrel earns moves between the runs: the shape, the capex of 2250.0000 and the fiscal terms are identical in all four."]'::jsonb, 3, 'Each run prices the same 20 year shape on the same 2250.0000 of capex, so a step of 15.0000 USD a barrel moves the value by the same amount every time.'),
  ('fdp', 'beginner', 'final', null, 25, 'The tie-back returns 1.436477 of NPV per million USD of capex against the FPSO''s 0.910029. What does a ranking on that ratio leave out?', '["Size: a ratio has none in it, and on a balance sheet that can carry 2250.0000 the FPSO leaves 2047.5653 million USD where the tie-back would have left 1048.6281.", "The price, because both ratios are conditional on the 70.0000 USD a barrel the two runs shared and the ranking between them turns over as soon as either is priced at 48.0000.", "The fiscal terms, because both pay royalty of 12.5000 percent on different volumes and the ratio is taken before the state is paid.", "The operating cost, because the tie-back''s 40.0000 a year against the FPSO''s 95.0000 sits outside the capex the ratio divides by."]'::jsonb, 0, '1048.6281 on 730.0000 of capex is the more efficient use of the money and 2047.5653 on 2250.0000 is the larger value, and the two measures answer different questions.'),
  ('fdp', 'beginner', 'final', null, 26, 'The Base case earns gross revenue of 16095.0492 million USD and reports a government take of 5321.9377. What is that take made of, and what share is it?', '["Tax of 3310.0565 on its own, because royalty is a cost of production charged ahead of the tax base and is already carried inside the operating cost of 3049.6464 million USD.", "Royalty of 2011.8812 and tax of 3310.0565 added together, which is 0.330657 of gross revenue, a ratio rather than a percent.", "Royalty of 2011.8812 and tax of 3310.0565 added, which is 0.330657 percent of gross revenue under the stated default rates of 12.5000 percent and 30.0000 percent.", "Royalty of 2011.8812, tax of 3310.0565 and the capex of 2250.0000 the state recovers through the fiscal terms, which is why the take runs well above the NPV of 2047.5653."]'::jsonb, 1, '2011.8812 plus 3310.0565 is 5321.9377 million USD, and 0.330657 of gross revenue is a plain ratio: 0.330657 percent of it would be a different figure entirely.'),
  ('fdp', 'beginner', 'final', null, 27, 'The Operate phase of the cost breakdown totals 355.0000 million USD while the plan''s OPEX total is 95.0000 a year. What accounts for the difference?', '["The 355.0000 is the operating cost with the variable 5.0000 USD a barrel added at full plateau, which is the same addition that puts 204.5000 into year 1 of the Base case.", "The 355.0000 is the two OPEX lines of 72.0000 and 23.0000 escalated across the 20.0000 year life of the concept, and the 95.0000 is the first year of that escalating series.", "The 355.0000 is the Installation phase read one row out, which totals 550.0000 from the mooring and the subsea system.", "The Operate roll-up carries the 260.0000 decommissioning provision beside the two OPEX lines, and it is money by phase rather than money a year."]'::jsonb, 3, 'Operations and logistics at 72.0000 plus Maintenance and integrity at 23.0000 make the 95.0000 a year, and the third line sitting in that phase is the 260.0000 ABEX provision.'),
  ('fdp', 'beginner', 'final', null, 28, 'The plan carries a decommissioning provision of 260.0000 million USD and the Egina FPSO carries a decommissioning figure of 204.5029. What does the screening case charge?', '["The 260.0000, in the final year of the 20.0000 year life, which is exactly why the Operate phase roll-up of 355.0000 stands so far above the annual operating cost of 95.0000.", "The 204.5029, because a facility figure is derived from the nameplate of 60000 bopd and the engine prefers a derived number.", "Neither of them: the case carries capex and operating cost only, so the 260.0000 falls outside the CAPEX total of 2250.0000 and outside the OPEX of 95.0000 a year.", "Both, as one abandonment line of the two added, which is what separates the lifecycle cost of 4150.0000 from the value of 2047.5653."]'::jsonb, 2, 'The engine totals CAPEX 2250.0000 and OPEX 95.0000 a year, so a value of 2047.5653 million USD is a screening value with an abandonment cost still to come.'),
  ('fdp', 'beginner', 'final', null, 29, 'A three year profile given two prices is refused. What does the refusal say, and what does the same profile do once a third price is entered?', '["It says the deck has no price for production year 3 and asks for a price for every year of the profile, and with three prices the case runs and returns an NPV of -202.4284.", "It says the scenario oil price is missing, which is the message a blank price returns, and with a third price entered the case runs and returns an NPV of -3517.4133.", "It extends the last price it holds across year 3 and warns that the deck was short, and with three prices returns the same value.", "It refuses the plan rather than the scenario, so completeness falls to 89 percent, and with the third price entered the plan reads 100 percent and prices normally again."]'::jsonb, 0, 'The message names the year: "the price deck has no price for production year 3: enter a price for every year of the profile", and the complete deck prices out at -202.4284.'),
  ('fdp', 'beginner', 'final', null, 30, 'Moving the Production driver up 30 percent takes the plan''s case to 3467.3636 million USD. What has that run done to the 130.0000 MMbbl the reserves table holds?', '["It raises the recoverable volume by the same 30 percent, because the sweep re-runs the whole case and the reserves table is one of the inputs that gets re-run with it, so the table and the profile stay in step through every row of the sweep.", "Nothing, and nothing checks it: the sweep scales the concept''s screening shape, and that shape was drawn from a peak rate and a life without consulting the reserves in the first place.", "It leaves the table alone but caps the run, since the engine stops the profile once cumulative production reaches the oil P50 of 130.0000 MMbbl.", "It swaps the oil P10 of 205.0000 MMbbl into the case in place of the P50, which is how the studio prices a production upside."]'::jsonb, 1, 'The shape already produces 229.9293 MMbbl against an oil P50 of 130.0000 MMbbl before the driver is moved at all, and the plan still scores complete and still returns a value.'),
  ('fdp', 'beginner', 'final', null, 31, 'The sweep moves the value by 3092.0051 on oil price and by 2839.5965 on production. Why is price the stronger of the two?', '["Production is capped by the concept''s peak rate of 60.0000 kbpd, so a rise of 30 percent cannot be delivered through the plateau years and only the declining years actually move.", "Royalty of 12.5000 percent falls on revenue from both drivers, while tax of 30.0000 percent is charged on the barrels alone.", "A move in the oil price also moves the capex of 2250.0000 through the cost items, so its swing carries a second effect.", "A barrel carries a variable operating cost of 5.0000 USD, so more barrels bring more cost with the revenue, while a dollar of price brings revenue and no cost."]'::jsonb, 3, 'Both drivers scale revenue, but 30 percent more barrels brings 30 percent more variable operating cost with it, which is why 3092.0051 runs above 2839.5965.'),
  ('fdp', 'beginner', 'final', null, 32, 'A reviewer subtracts the FPSO concept''s lifecycle cost of 4150.0000 million USD from the Base case''s gross revenue of 16095.0492 and calls the remainder what the development is worth. What has that produced?', '["The undiscounted value of the development, which becomes the 2047.5653 million USD once the 10.0000 percent rate has been applied to it year by year across the 21 rows the case carries.", "The right figure on the wrong scale, since gross revenue is money across the whole life and a lifecycle cost is money as it is spent, so the two would have to be put on one basis before either could be taken from the other.", "A figure on no scale the studio uses: it leaves the royalty of 2011.8812 and the tax of 3310.0565 inside the revenue and discounts nothing, while the value on those terms is 2047.5653 million USD.", "The government take of 5321.9377 million USD reached the long way round, because royalty and tax are exactly what separate gross revenue from a lifecycle cost."]'::jsonb, 2, 'A lifecycle cost is a plain sum of capex and operating cost with no price, no fiscal terms and no discounting in it, so it cannot be subtracted from a revenue to leave a value.'),
  ('fdp', 'beginner', 'final', null, 33, 'A gas only plan scores 33 percent with isValid true, a plan with a value of exactly zero scores 0 percent and one with a negative value scores 11 percent. What do those say about the score?', '["That it counts sections carrying something and cannot tell a calculated zero from a box nobody filled in, so it measures what is present and never whether any of it is right.", "That the nine sections are weighted by importance, which is how the economics section alone moves a plan between 0 percent and 11 percent while the reserves section cannot.", "That a plan is scored against the fluids it carries, so a gas only plan is measured against a shorter list of sections and reaches isValid true at a third of the full score.", "That each section is rounded to the nearest ninth of the total, which is what puts a plan with a value of zero at 0 percent and one with a negative value at 11 percent."]'::jsonb, 0, 'A negative value counts as economics done and scores 11 percent while a zero does not, because the check cannot tell a calculated zero from a field nobody ever filled in.'),
  ('fdp', 'beginner', 'final', null, 34, 'A worked answer reports an oil reserves figure, a rate of return and a value per million USD of capex. What unit does each of the three carry?', '["MMbbl for the oil, a ratio for the rate of return, and million USD for the value per million USD of capex, which is why it prints as 1.436477 alongside the money in the plan.", "MMbbl for the oil, percent for the rate of return such as 29.5998, and a plain number for the ratio such as 1.436477.", "A barrel of oil equivalent basis for the oil once the 70.0000 Bcf of gas has been carried into it, percent for the rate of return, and percent again for the ratio that follows it.", "MMbbl for the oil, percent for the rate of return of 29.5998 and for the government take of 0.330657 as well, and million USD for the value per million USD of capex."]'::jsonb, 1, 'A percent and a ratio are different animals: 0.330657 of gross revenue is not 0.330657 percent of it, and 1.436477 is a plain number carrying no unit at all.'),
  ('fdp', 'beginner', 'final', null, 35, 'A question asks what a concept is worth and the plan carries no annual operating cost for that concept. What is the answer?', '["The value taken on the default operating cost of 10 million USD a year, which is what the engine ran on before the repair and remains the figure to assume where the field is blank.", "The value taken on the plan''s own OPEX total of 95.0000 million USD a year, because the cost items carry an operating cost for the field even when the concept record does not.", "That the figure is missing: the engine stops with \"the concept annual operating cost is missing\" and names the field to go and fill in.", "A value computed at 0.0000 of operating cost, because a screening case charges only what it has been given."]'::jsonb, 2, 'A guessed input produces an output with no owner, so the engine names the field instead, and where the plan cannot say what something is worth the answer is what is missing.'),
  ('fdp', 'beginner', 'final', null, 36, 'The teaching schedule''s activities give a network duration of 870 days against a calendar span of 933 days on the dates typed across them. What is the 63 days?', '["The float carried by the three activities that sit off the critical path, which hold 180 days, 180 days and 480 days respectively before the finish date is moved by any of them.", "The days lost to weekends and public holidays, because a network duration counts only working days while a calendar span counts every day between the first date and the last one.", "An error in the dates, because a network of 870 days and a span of 933 days cannot both be right and the engine reports the difference so that the typed dates can be corrected.", "Float already spent in the calendar: the window is wider than the work the network says has to happen."]'::jsonb, 3, '870 days is how long the work must take and 933 days is how wide the window is, so 63 days of that window is not needed by the logic of the network.'),
  ('fdp', 'beginner', 'final', null, 37, 'The EGINA register''s five cost impacts add to 1145.0000 million USD and its exposure reads 269.0000. What is the 269.0000?', '["The expected value at the engine''s probability factors, of which the critical risk contributes 108.0000, and it is not the worst case the register describes.", "The worst case with the unscored risk taken out of it, since Host government approval carries 400.0000 million USD of cost impact and no probability to weight that figure with.", "The cost impacts of the scored risks added once the unscored one is dropped, which is what the four bands contribute.", "The register''s total cost impact weighted by the portfolio health of 58, so exposure and health always move in step."]'::jsonb, 0, '269.0000 million USD is the probability weighted total, 1145.0000 is what the register would cost if every risk happened, and the critical risk alone contributes 108.0000.'),
  ('fdp', 'beginner', 'final', null, 38, 'A plan reports P50 oil 130.0000 MMbbl, P50 gas 70.0000 Bcf, CAPEX 2250.0000, NPV 2047.5653, IRR 29.5998 and 4 wells. What does a reader need before quoting that NPV?', '["The completeness score, because a plan below 100 percent carries an error list and an NPV quoted off an incomplete plan is exactly the case the studio puts a warning against.", "The gas P50 of 70.0000 Bcf, because the screening case prices both fluids and a value quoted without it understates the field.", "Which capex it ran on, which price priced it and which production shape it burned, because the figure is one concept at 70.0000 USD a barrel on default terms.", "The well count of 4, because the capex of 2250.0000 is divided across the wells the list carries."]'::jsonb, 2, '2047.5653 million USD belongs to the FPSO concept at 70.0000 USD a barrel on 2250.0000 of capex and a 20 year shape, and at 18.0000 USD a barrel the same concept reads -1797.2732.'),
  ('fdp', 'beginner', 'final', null, 39, 'A plan carries a reserves row of 95.0000 MMbbl at P50 for Egina Main and a well at 14200 ft of measured depth. What did the studio contribute to either of those two figures?', '["It derived both, the reserves row from the zone''s 403.5392 MMstb of oil in place at a recovery factor of 0.340000, and the depth from the drilling capex of 520.0000 million USD the concept carries, before it would let either figure reach the generated document.", "Nothing beyond holding them: a subsurface team handed over the 95.0000 and somebody designed the 14200 ft trajectory, and the studio adds the oil rows to 130.0000 MMbbl without ever checking the geology.", "It checked both against the engine''s published cases and would have flagged either one for falling outside the range those cases cover, which is the check a plan carrying figures of this kind is supposed to survive.", "It set the 95.0000 MMbbl from the recovery factor of 0.340000 that the row carries, which is the one column in the reserves table the engine computes rather than reads."]'::jsonb, 1, 'A figure typed into the studio is only as good as the work behind it, and the totalling, the dating and the pricing are the whole of what the studio adds to it.'),
  ('fdp', 'beginner', 'final', null, 40, 'Two fields show the same figure when their oil and gas P50 totals are added together. What does a screening case say about the pair?', '["It prices both fluids at the scenario''s oil price of 70.0000 USD a barrel, so the two fields are worth the same figure until somebody enters a separate price for the gas.", "It refuses a combined figure in the way it refuses a row typed as Brine, so neither field can be screened at all until the two fluid totals are reported separately again.", "It converts the gas onto a barrel of oil equivalent basis at the engine''s own factor, which is the conversion that makes a combined figure such as 200.0000 mean something.", "It prices barrels only, so the gas never enters the value and the two can be worth entirely different money."]'::jsonb, 3, 'EGINA''s oil P50 of 130.0000 MMbbl and gas P50 of 70.0000 Bcf are never added, and the screening case runs on the oil shape the concept implies.'),
  ('fdp', 'beginner', 'final', null, 41, 'The concept''s capex of 2250.0000 million USD and the cost items'' CAPEX total of 2250.0000 agree exactly. Is that agreement a rule of the studio?', '["No: the plan was costed against the concept it runs, and the studio will price a plan whose items total something else entirely and report both figures without complaint.", "Yes: the engine reads a concept''s capex from the cost item list, which is why the drilling line of 520.0000 matches the concept''s own drilling field to the decimal.", "Yes: a plan whose two totals disagree fails validation with \"Total CAPEX is zero or missing.\" until one of the two has been corrected to match the other.", "No, but the gap is bounded by the facility screening estimate of 1363.3524 million USD, held so one total can check the other."]'::jsonb, 0, 'They are two answers to one question, one from a concept type and a size and one from a list of seven purchases, and a plan where they differ has a question inside it.'),
  ('fdp', 'beginner', 'final', null, 42, 'Two habits this tier insists on are carrying figures at the precision they were printed at and never answering about one model with a number from another. What goes wrong when either is dropped?', '["Rounding as you go loses the unit and a borrowed number brings its own, so both faults surface as money where a ratio was wanted.", "Rounding as you go moves the last figures, and a number borrowed across models is wrong even where it looks plausible, because the models in this course share nothing.", "Rounding as you go is safe wherever the engine prints four decimals, so only the borrowed number matters at all.", "Rounding as you go is caught by the completeness check and a borrowed number by the refusal that names a field."]'::jsonb, 1, 'Carry each figure at the precision it was printed at, do the arithmetic once, and keep a development plan in million USD apart from a project schedule in whole currency units.');
