-- ============================================================================
-- EC6 ASSOCIATE DEEP SEED: Field Development Planning, beginner tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed.
--
-- What this tier owns: THE PLAN AND ITS MONEY. What a plan holds and refuses
-- to guess, reserves totalled one fluid at a time, the three capex fields a
-- concept carries, what a scenario is worth after royalty and tax, and the
-- plan's own cost items against the concept's estimate.
--
-- THE ENGINE FACT THIS TIER OWNS. A figure the plan does not carry is refused
-- by name. The retired engine substituted 100 million USD of capex, 10 million
-- USD a year of operating cost, 50 kbpd of peak rate and 70 USD a barrel, all
-- silently, and put a full set of economics on the card.
--
-- THE TRAP THE TIER IS BUILT ON. Oil in MMbbl and gas in Bcf are never added,
-- and a plan that cannot be costed yet gets a list of what is missing rather
-- than a number.
-- ============================================================================

values ('fdp', 'beginner', '{"modules":[{"key":"m01-what-a-plan-holds","title":"What a Plan Holds","lesson_keys":["l01-one-field-one-plan","l02-what-this-studio-does-not-do","l03-the-screening-tier","l04-what-it-refuses-to-guess"]},{"key":"m02-reserves-per-fluid","title":"Reserves, One Total per Fluid","lesson_keys":["l01-a-table-of-reservoirs","l02-oil-is-not-gas","l03-a-sum-of-low-cases","l04-the-plan-s-own-p50","l05-volumetrics-behind-the-number"]},{"key":"m03-concepts-and-their-capex","title":"Concepts and Their Capex","lesson_keys":["l01-three-capex-fields","l02-lifecycle-cost","l03-the-shape-a-concept-implies","l04-dating-a-concept"]},{"key":"m04-what-a-scenario-is-worth","title":"What a Scenario Is Worth","lesson_keys":["l01-price-is-an-input-not-a-fact","l02-npv-after-royalty-and-tax","l03-the-year-the-money-goes-out","l04-payback-and-what-it-hides","l05-two-concepts-one-price"]},{"key":"m05-the-plan-s-own-economics","title":"The Plan''s Own Economics","lesson_keys":["l01-cost-items-are-the-money","l02-capex-opex-and-the-line-left-out","l03-a-deck-that-does-not-cover-the-profile","l04-what-moves-the-answer","l05-no-economics-yet"]},{"key":"m06-the-associate-reading","title":"The Associate Reading","lesson_keys":["l01-the-story-so-far","l02-working-the-capstone","l03-onward"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
